const input_handler = {
  name: 'input_handler',

  keys: {},

  init(state) {
    state.write('input_keys', {
      fireboy: { left: false, right: false, jump: false },
      watergirl: { left: false, right: false, jump: false }
    });

    this.keys = {};

    window.addEventListener('keydown', (e) => {
      this.keys[e.code] = true;
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) {
        e.preventDefault();
      }
    });

    window.addEventListener('keyup', (e) => {
      this.keys[e.code] = false;
    });

    window.addEventListener('blur', () => {
      this.keys = {};
    });
  },

  update(state, dt) {
    const inputState = {
      fireboy: {
        left: !!(this.keys['KeyA']),
        right: !!(this.keys['KeyD']),
        jump: !!(this.keys['KeyW'])
      },
      watergirl: {
        left: !!(this.keys['ArrowLeft']),
        right: !!(this.keys['ArrowRight']),
        jump: !!(this.keys['ArrowUp'])
      }
    };

    state.write('input_keys', inputState);
  },

  render(state, ctx) {
  }
};

export default input_handler;

