const CharacterState = {
  name: 'CharacterState',

  init(state) {
    state.write('player_state', {
      fireboy: {
        position: { x: 100, y: 300 },
        state: 'alive',
        deathTimer: 0,
        respawnTime: 2000,
        animFrame: 0,
        animTimer: 0,
        facing: 1
      },
      watergirl: {
        position: { x: 150, y: 300 },
        state: 'alive',
        deathTimer: 0,
        respawnTime: 2000,
        animFrame: 0,
        animTimer: 0,
        facing: 1
      },
      levelRestart: false,
      bothDead: false,
      checkpoint: { x: 100, y: 300 }
    });
  },

  update(state, dt) {
    const playerState = state.read('player_state');
    const entityPositions = state.read('entity_positions');
    const hazardZones = state.read('hazard_zones');

    if (!playerState) return;

    const positions = entityPositions || {};
    const hazards = hazardZones || { waterZones: [], fireZones: [], lavaZones: [] };

    // Sync positions from entity_positions
    if (positions.fireboy) {
      playerState.fireboy.position = { ...positions.fireboy };
    }
    if (positions.watergirl) {
      playerState.watergirl.position = { ...positions.watergirl };
    }

    // Update facing direction based on velocity
    if (positions.fireboyVelocity) {
      playerState.fireboy.facing = positions.fireboyVelocity.x >= 0 ? 1 : -1;
    }
    if (positions.watergirlVelocity) {
      playerState.watergirl.facing = positions.watergirlVelocity.x >= 0 ? 1 : -1;
    }

    // Check hazard collisions for Fireboy (dies in water)
    if (playerState.fireboy.state === 'alive') {
      const fbPos = playerState.fireboy.position;
      for (const zone of (hazards.waterZones || [])) {
        if (this.boxCollision(fbPos, zone, 20, 36)) {
          playerState.fireboy.state = 'dead';
          playerState.fireboy.deathTimer = 0;
          break;
        }
      }
    }

    // Check hazard collisions for Watergirl (dies in fire/lava)
    if (playerState.watergirl.state === 'alive') {
      const wgPos = playerState.watergirl.position;
      const fireZones = (hazards.fireZones || []).concat(hazards.lavaZones || []);
      for (const zone of fireZones) {
        if (this.boxCollision(wgPos, zone, 20, 36)) {
          playerState.watergirl.state = 'dead';
          playerState.watergirl.deathTimer = 0;
          break;
        }
      }
    }

    // Update character states
    this.updateCharacter(playerState.fireboy, dt, playerState.checkpoint);
    this.updateCharacter(playerState.watergirl, dt, playerState.checkpoint);

    // Check if both characters are incapacitated
    const fbIncapacitated = playerState.fireboy.state === 'dead' || playerState.fireboy.state === 'respawning';
    const wgIncapacitated = playerState.watergirl.state === 'dead' || playerState.watergirl.state === 'respawning';

    playerState.bothDead = fbIncapacitated && wgIncapacitated;

    // Trigger level restart signal
    if (playerState.bothDead && !playerState.levelRestart) {
      playerState.levelRestart = true;
      playerState.restartTimer = 0;
    }

    if (playerState.levelRestart) {
      playerState.restartTimer = (playerState.restartTimer || 0) + dt * 1000;
      if (playerState.restartTimer > 1500) {
        this.resetToCheckpoint(playerState);
      }
    }

    // Update animations
    this.updateAnimation(playerState.fireboy, dt);
    this.updateAnimation(playerState.watergirl, dt);

    state.write('player_state', playerState);
  },

  boxCollision(pos, zone, width, height) {
    const halfW = width / 2;
    const halfH = height / 2;
    return pos.x + halfW > zone.x &&
           pos.x - halfW < zone.x + zone.width &&
           pos.y + halfH > zone.y &&
           pos.y - halfH < zone.y + zone.height;
  },

  updateCharacter(char, dt, checkpoint) {
    if (char.state === 'dead') {
      char.deathTimer += dt * 1000;
      if (char.deathTimer >= char.respawnTime) {
        char.state = 'respawning';
        char.deathTimer = 0;
      }
    } else if (char.state === 'respawning') {
      char.deathTimer += dt * 1000;
      if (char.deathTimer >= 500) {
        char.state = 'alive';
        char.position = { ...checkpoint };
        char.deathTimer = 0;
      }
    }
  },

  resetToCheckpoint(playerState) {
    playerState.fireboy.state = 'alive';
    playerState.watergirl.state = 'alive';
    playerState.fireboy.position = { ...playerState.checkpoint };
    playerState.watergirl.position = { x: playerState.checkpoint.x + 50, y: playerState.checkpoint.y };
    playerState.fireboy.deathTimer = 0;
    playerState.watergirl.deathTimer = 0;
    playerState.levelRestart = false;
    playerState.bothDead = false;
    playerState.restartTimer = 0;
  },

  updateAnimation(char, dt) {
    char.animTimer = (char.animTimer || 0) + dt * 1000;
    if (char.animTimer > 120) {
      char.animFrame = (char.animFrame + 1) % 4;
      char.animTimer = 0;
    }
  },

  render(state, ctx) {
    const playerState = state.read('player_state');
    if (!playerState) return;

    this.renderFireboy(ctx, playerState.fireboy);
    this.renderWatergirl(ctx, playerState.watergirl);

    // Render death overlay if both dead
    if (playerState.bothDead) {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
      ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);

      ctx.fillStyle = '#ff4444';
      ctx.font = 'bold 32px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('RESTARTING...', ctx.canvas.width / 2, ctx.canvas.height / 2);
    }
  },

  renderFireboy(ctx, char) {
    const pos = char.position;
    const frame = char.animFrame;
    const facing = char.facing;

    ctx.save();
    ctx.translate(pos.x, pos.y);

    // Death state effects
    if (char.state === 'dead') {
      ctx.rotate(Math.PI / 6);
      ctx.globalAlpha = 0.5 + Math.sin(Date.now() / 100) * 0.3;
    } else if (char.state === 'respawning') {
      ctx.globalAlpha = Math.sin(Date.now() / 80) * 0.5 + 0.5;
    }

    ctx.scale(facing, 1);

    // Flame aura
    const auraSize = 18 + Math.sin(Date.now() / 150) * 3;
    const gradient = ctx.createRadialGradient(0, -5, 0, 0, -5, auraSize);
    gradient.addColorStop(0, 'rgba(255, 200, 50, 0.4)');
    gradient.addColorStop(1, 'rgba(255, 100, 0, 0)');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(0, -5, auraSize, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = '#ff6b1a';
    ctx.beginPath();
    ctx.ellipse(0, 5, 10, 14, 0, 0, Math.PI * 2);
    ctx.fill();

    // Flame hair
    const flicker = [0, 2, -1, 3][frame];
    ctx.fillStyle = '#ffcc00';
    ctx.beginPath();
    ctx.moveTo(-9, -8);
    ctx.quadraticCurveTo(-6, -22 + flicker, 0, -16);
    ctx.quadraticCurveTo(6, -25 + flicker, 9, -8);
    ctx.closePath();
    ctx.fill();

    // Inner flame
    ctx.fillStyle = '#fff176';
    ctx.beginPath();
    ctx.moveTo(-5, -6);
    ctx.quadraticCurveTo(-2, -16 + flicker, 0, -10);
    ctx.quadraticCurveTo(2, -14 + flicker, 5, -6);
    ctx.closePath();
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath();
    ctx.arc(-4, 0, 2.5, 0, Math.PI * 2);
    ctx.arc(4, 0, 2.5, 0, Math.PI * 2);
    ctx.fill();

    // Eye shine
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(-3, -1, 1, 0, Math.PI * 2);
    ctx.arc(5, -1, 1, 0, Math.PI * 2);
    ctx.fill();

    // Determined expression
    ctx.strokeStyle = '#cc4400';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 6, 4, 0.2, Math.PI - 0.2);
    ctx.stroke();

    // Legs with walk cycle
    const legAnim = Math.sin(frame * Math.PI / 2) * 5;
    ctx.fillStyle = '#cc4400';
    ctx.fillRect(-8, 17, 5, 12 + legAnim);
    ctx.fillRect(3, 17, 5, 12 - legAnim);

    // Feet
    ctx.fillStyle = '#992200';
    ctx.fillRect(-9, 27 + legAnim, 7, 4);
    ctx.fillRect(2, 27 - legAnim, 7, 4);

    ctx.restore();
  },

  renderWatergirl(ctx, char) {
    const pos = char.position;
    const frame = char.animFrame;
    const facing = char.facing;

    ctx.save();
    ctx.translate(pos.x, pos.y);

    // Death state effects
    if (char.state === 'dead') {
      ctx.rotate(-Math.PI / 6);
      ctx.globalAlpha = 0.5 + Math.sin(Date.now() / 100) * 0.3;
    } else if (char.state === 'respawning') {
      ctx.globalAlpha = Math.sin(Date.now() / 80) * 0.5 + 0.5;
    }

    ctx.scale(facing, 1);

    // Water aura
    const auraSize = 16 + Math.sin(Date.now() / 200) * 2;
    const gradient = ctx.createRadialGradient(0, -5, 0, 0, -5, auraSize);
    gradient.addColorStop(0, 'rgba(100, 200, 255, 0.3)');
    gradient.addColorStop(1, 'rgba(0, 100, 200, 0)');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(0, -5, auraSize, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = '#4fc3f7';
    ctx.beginPath();
    ctx.ellipse(0, 5, 9, 13, 0, 0, Math.PI * 2);
    ctx.fill();

    // Water drop hair
    const wave = [0, -1, 1, -2][frame];
    ctx.fillStyle = '#0288d1';
    ctx.beginPath();
    ctx.moveTo(-7, -7);
    ctx.quadraticCurveTo(-5, -20 + wave, 0, -26 + wave);
    ctx.quadraticCurveTo(5, -20 + wave, 7, -7);
    ctx.closePath();
    ctx.fill();

    // Hair highlight
    ctx.fillStyle = '#81d4fa';
    ctx.beginPath();
    ctx.moveTo(-3, -10);
    ctx.quadraticCurveTo(-1, -18 + wave, 0, -22 + wave);
    ctx.quadraticCurveTo(1, -18 + wave, 3, -10);
    ctx.closePath();
    ctx.fill();

    // Water droplet decoration
    ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
    ctx.beginPath();
    ctx.arc(-4, -20 + wave, 2, 0, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath();
    ctx.arc(-4, 1, 2.5, 0, Math.PI * 2);
    ctx.arc(4, 1, 2.5, 0, Math.PI * 2);
    ctx.fill();

    // Eye shine
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(-3, 0, 1, 0, Math.PI * 2);
    ctx.arc(5, 0, 1, 0, Math.PI * 2);
    ctx.fill();

    // Gentle smile
    ctx.strokeStyle = '#01579b';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 5, 4, 0.3, Math.PI - 0.3);
    ctx.stroke();

    // Legs with walk cycle
    const legAnim = Math.sin(frame * Math.PI / 2) * 5;
    ctx.fillStyle = '#0288d1';
    ctx.fillRect(-6, 16, 5, 10 + legAnim);
    ctx.fillRect(1, 16, 5, 10 - legAnim);

    // Feet
    ctx.fillStyle = '#01579b';
    ctx.fillRect(-7, 24 + legAnim, 7, 4);
    ctx.fillRect(0, 24 - legAnim, 7, 4);

    ctx.restore();
  }
};

export default CharacterState;

const CharacterState = {
  name: 'CharacterState',

  init(state) {
    state.write('player_state', {
      fireboy: {
        position: { x: 100, y: 300 },
        state: 'alive',
        deathTimer: 0,
        respawnTime: 2000,
        animFrame: 0,
        animTimer: 0,
        facing: 1,
        velocity: { x: 0, y: 0 }
      },
      watergirl: {
        position: { x: 150, y: 300 },
        state: 'alive',
        deathTimer: 0,
        respawnTime: 2000,
        animFrame: 0,
        animTimer: 0,
        facing: 1,
        velocity: { x: 0, y: 0 }
      },
      levelRestart: false,
      bothDead: false,
      checkpoint: { fireboy: { x: 100, y: 300 }, watergirl: { x: 150, y: 300 } }
    });
  },

  update(state, dt) {
    const playerState = state.read('player_state');
    const entityPositions = state.read('entity_positions');
    const hazardZones = state.read('hazard_zones');

    if (!playerState) return;

    const positions = entityPositions || {};
    const hazards = hazardZones || { waterZones: [], fireZones: [], lavaZones: [], gooZones: [] };

    // Sync positions from entity_positions
    if (positions.fireboy) {
      playerState.fireboy.position = { ...positions.fireboy };
    }
    if (positions.watergirl) {
      playerState.watergirl.position = { ...positions.watergirl };
    }
    if (positions.fireboyVelocity) {
      playerState.fireboy.velocity = { ...positions.fireboyVelocity };
      if (positions.fireboyVelocity.x !== 0) {
        playerState.fireboy.facing = positions.fireboyVelocity.x > 0 ? 1 : -1;
      }
    }
    if (positions.watergirlVelocity) {
      playerState.watergirl.velocity = { ...positions.watergirlVelocity };
      if (positions.watergirlVelocity.x !== 0) {
        playerState.watergirl.facing = positions.watergirlVelocity.x > 0 ? 1 : -1;
      }
    }

    // Animation update
    const animSpeed = 100;
    const isMoving = (v) => Math.abs(v.x) > 0.1 || Math.abs(v.y) > 0.1;

    if (isMoving(playerState.fireboy.velocity) && playerState.fireboy.state === 'alive') {
      playerState.fireboy.animTimer += dt * 1000;
      if (playerState.fireboy.animTimer > animSpeed) {
        playerState.fireboy.animFrame = (playerState.fireboy.animFrame + 1) % 4;
        playerState.fireboy.animTimer = 0;
      }
    }

    if (isMoving(playerState.watergirl.velocity) && playerState.watergirl.state === 'alive') {
      playerState.watergirl.animTimer += dt * 1000;
      if (playerState.watergirl.animTimer > animSpeed) {
        playerState.watergirl.animFrame = (playerState.watergirl.animFrame + 1) % 4;
        playerState.watergirl.animTimer = 0;
      }
    }

    // Hazard collision checks for alive characters
    if (playerState.fireboy.state === 'alive' && playerState.fireboy.position) {
      const pos = playerState.fireboy.position;
      // Fireboy dies in water
      for (const zone of (hazards.waterZones || [])) {
        if (this.boxCollision(pos.x - 12, pos.y - 20, 24, 40, zone)) {
          playerState.fireboy.state = 'dead';
          playerState.fireboy.deathTimer = 0;
          break;
        }
      }
      // Fireboy dies in lava
      if (playerState.fireboy.state === 'alive') {
        for (const zone of (hazards.lavaZones || [])) {
          if (this.boxCollision(pos.x - 12, pos.y - 20, 24, 40, zone)) {
            playerState.fireboy.state = 'dead';
            playerState.fireboy.deathTimer = 0;
            break;
          }
        }
      }
      // Goo kills both
      if (playerState.fireboy.state === 'alive') {
        for (const zone of (hazards.gooZones || [])) {
          if (this.boxCollision(pos.x - 12, pos.y - 20, 24, 40, zone)) {
            playerState.fireboy.state = 'dead';
            playerState.fireboy.deathTimer = 0;
            break;
          }
        }
      }
    }

    if (playerState.watergirl.state === 'alive' && playerState.watergirl.position) {
      const pos = playerState.watergirl.position;
      // Watergirl dies in fire
      for (const zone of (hazards.fireZones || [])) {
        if (this.boxCollision(pos.x - 12, pos.y - 20, 24, 40, zone)) {
          playerState.watergirl.state = 'dead';
          playerState.watergirl.deathTimer = 0;
          break;
        }
      }
      // Watergirl dies in lava
      if (playerState.watergirl.state === 'alive') {
        for (const zone of (hazards.lavaZones || [])) {
          if (this.boxCollision(pos.x - 12, pos.y - 20, 24, 40, zone)) {
            playerState.watergirl.state = 'dead';
            playerState.watergirl.deathTimer = 0;
            break;
          }
        }
      }
      // Goo kills both
      if (playerState.watergirl.state === 'alive') {
        for (const zone of (hazards.gooZones || [])) {
          if (this.boxCollision(pos.x - 12, pos.y - 20, 24, 40, zone)) {
            playerState.watergirl.state = 'dead';
            playerState.watergirl.deathTimer = 0;
            break;
          }
        }
      }
    }

    // Handle death timers
    if (playerState.fireboy.state === 'dead') {
      playerState.fireboy.deathTimer += dt * 1000;
      if (playerState.fireboy.deathTimer >= playerState.fireboy.respawnTime) {
        playerState.fireboy.state = 'respawning';
        playerState.fireboy.deathTimer = 0;
      }
    }

    if (playerState.watergirl.state === 'dead') {
      playerState.watergirl.deathTimer += dt * 1000;
      if (playerState.watergirl.deathTimer >= playerState.watergirl.respawnTime) {
        playerState.watergirl.state = 'respawning';
        playerState.watergirl.deathTimer = 0;
      }
    }

    // Check if both dead - trigger level restart
    const bothDead = playerState.fireboy.state === 'dead' && playerState.watergirl.state === 'dead';
    if (bothDead && !playerState.bothDead) {
      playerState.levelRestart = true;
    }
    playerState.bothDead = bothDead;

    state.write('player_state', playerState);
  },

  boxCollision(x, y, w, h, zone) {
    if (!zone) return false;
    return x < zone.x + zone.width &&
           x + w > zone.x &&
           y < zone.y + zone.height &&
           y + h > zone.y;
  },

  render(state, ctx) {
    const playerState = state.read('player_state');
    if (!playerState) return;

    this.renderCharacter(ctx, playerState.fireboy, 'fireboy');
    this.renderCharacter(ctx, playerState.watergirl, 'watergirl');
  },

  renderCharacter(ctx, character, type) {
    const pos = character.position;
    if (!pos) return;

    ctx.save();

    const isDead = character.state === 'dead';
    const isRespawning = character.state === 'respawning';
    const blinkAlpha = isRespawning ? 0.5 + Math.sin(Date.now() / 80) * 0.4 : 1;
    ctx.globalAlpha = isDead ? 0.2 : blinkAlpha;

    const facing = character.facing || 1;
    ctx.translate(pos.x, pos.y);
    ctx.scale(facing, 1);

    const legOffset = Math.sin(character.animFrame * Math.PI / 2) * 4;

    if (type === 'fireboy') {
      // Legs
      ctx.strokeStyle = '#CC4400';
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(-5, 10);
      ctx.lineTo(-8 - legOffset, 25);
      ctx.moveTo(5, 10);
      ctx.lineTo(8 + legOffset, 25);
      ctx.stroke();

      // Body
      ctx.fillStyle = '#FF6B00';
      ctx.beginPath();
      ctx.ellipse(0, -5, 12, 18, 0, 0, Math.PI * 2);
      ctx.fill();

      // Flame hair
      ctx.fillStyle = '#FFCC00';
      const flicker = Math.sin(Date.now() / 60) * 2;
      ctx.beginPath();
      ctx.moveTo(-10, -20);
      ctx.quadraticCurveTo(-8, -35 + flicker, -4, -22);
      ctx.quadraticCurveTo(0, -40 + flicker, 4, -22);
      ctx.quadraticCurveTo(8, -35 + flicker, 10, -20);
      ctx.closePath();
      ctx.fill();

      // Inner flame
      ctx.fillStyle = '#FFFF66';
      ctx.beginPath();
      ctx.moveTo(-6, -20);
      ctx.quadraticCurveTo(-4, -30 + flicker, 0, -22);
      ctx.quadraticCurveTo(4, -30 + flicker, 6, -20);
      ctx.closePath();
      ctx.fill();

      // Eyes
      ctx.fillStyle = '#FFF';
      ctx.beginPath();
      ctx.arc(-5, -8, 3, 0, Math.PI * 2);
      ctx.arc(5, -8, 3, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#000';
      ctx.beginPath();
      ctx.arc(-5, -8, 1.5, 0, Math.PI * 2);
      ctx.arc(5, -8, 1.5, 0, Math.PI * 2);
      ctx.fill();

    } else {
      // Watergirl
      // Legs
      ctx.strokeStyle = '#0066AA';
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(-5, 10);
      ctx.lineTo(-8 - legOffset, 25);
      ctx.moveTo(5, 10);
      ctx.lineTo(8 + legOffset, 25);
      ctx.stroke();

      // Body
      ctx.fillStyle = '#4FC3F7';
      ctx.beginPath();
      ctx.ellipse(0, -5, 12, 18, 0, 0, Math.PI * 2);
      ctx.fill();

      // Ice crystal hair
      ctx.fillStyle = '#81D4FA';
      ctx.beginPath();
      ctx.moveTo(-12, -20);
      ctx.lineTo(-8, -38);
      ctx.lineTo(-4, -20);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(-2, -22);
      ctx.lineTo(2, -42);
      ctx.lineTo(6, -22);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(4, -20);
      ctx.lineTo(8, -38);
      ctx.lineTo(12, -20);
      ctx.fill();

      // Sparkle effect
      ctx.fillStyle = 'rgba(255,255,255,0.8)';
      const sparkle = (Date.now() / 200) % 1;
      ctx.beginPath();
      ctx.arc(-6 + sparkle * 4, -30 - sparkle * 3, 1.5, 0, Math.PI * 2);
      ctx.arc(4 - sparkle * 3, -35 + sparkle * 2, 1, 0, Math.PI * 2);
      ctx.fill();

      // Eyes
      ctx.fillStyle = '#FFF';
      ctx.beginPath();
      ctx.arc(-5, -8, 3, 0, Math.PI * 2);
      ctx.arc(5, -8, 3, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#003366';
      ctx.beginPath();
      ctx.arc(-5, -8, 1.5, 0, Math.PI * 2);
      ctx.arc(5, -8, 1.5, 0, Math.PI * 2);
      ctx.fill();
    }

    // Death effect
    if (isDead) {
      ctx.globalAlpha = 0.6;
      ctx.fillStyle = type === 'fireboy' ? '#0066FF' : '#FF3300';
      for (let i = 0; i < 5; i++) {
        const angle = (Date.now() / 100 + i * 72) * Math.PI / 180;
        const dist = 15 + Math.sin(Date.now() / 150 + i) * 5;
        ctx.beginPath();
        ctx.arc(Math.cos(angle) * dist, Math.sin(angle) * dist - 5, 4, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    ctx.restore();
  }
};

