const ElementalAffinity = {
  name: 'ElementalAffinity',

  init(state) {
    state.write('player_state', {
      fireboy: {
        alive: true,
        health: 100,
        invulnerable: false,
        invulnerableTimer: 0,
        deathReason: null,
        animFrame: 0
      },
      watergirl: {
        alive: true,
        health: 100,
        invulnerable: false,
        invulnerableTimer: 0,
        deathReason: null,
        animFrame: 0
      },
      gameOver: false,
      winner: null
    });
  },

  update(state, dt) {
    const positions = state.read('entity_positions');
    const hazards = state.read('hazard_zones');
    const playerState = state.read('player_state');

    if (!playerState) return;

    const newState = JSON.parse(JSON.stringify(playerState));

    if (newState.fireboy.invulnerableTimer > 0) {
      newState.fireboy.invulnerableTimer -= dt;
      if (newState.fireboy.invulnerableTimer <= 0) {
        newState.fireboy.invulnerable = false;
      }
    }

    if (newState.watergirl.invulnerableTimer > 0) {
      newState.watergirl.invulnerableTimer -= dt;
      if (newState.watergirl.invulnerableTimer <= 0) {
        newState.watergirl.invulnerable = false;
      }
    }

    if (positions && hazards && newState.fireboy.alive) {
      this.processHazardInteractions(positions.fireboy, hazards, 'fireboy', newState, dt);
    }

    if (positions && hazards && newState.watergirl.alive) {
      this.processHazardInteractions(positions.watergirl, hazards, 'watergirl', newState, dt);
    }

    newState.animTime = (newState.animTime || 0) + dt;
    newState.fireboy.animFrame = Math.floor((newState.animTime || 0) * 8) % 4;
    newState.watergirl.animFrame = Math.floor((newState.animTime || 0) * 8) % 4;

    if (!newState.fireboy.alive && !newState.watergirl.alive) {
      newState.gameOver = true;
      newState.winner = null;
    }

    state.write('player_state', newState);
  },

  processHazardInteractions(entityPos, hazards, entityType, newState, dt) {
    if (!entityPos || !hazards) return;

    const playerState = newState[entityType];

    for (const hazard of hazards) {
      if (this.checkCollision(entityPos, hazard)) {
        const interaction = this.getElementalInteraction(entityType, hazard.type);

        if (interaction === 'immune') {
          playerState.inHazardZone = hazard.type;
        } else if (interaction === 'vulnerable' && !playerState.invulnerable) {
          playerState.alive = false;
          playerState.health = 0;
          playerState.deathReason = hazard.type;
          playerState.deathTime = Date.now();
        } else if (interaction === 'damage' && !playerState.invulnerable) {
          playerState.health -= 20 * dt;
          if (playerState.health <= 0) {
            playerState.alive = false;
            playerState.health = 0;
            playerState.deathReason = hazard.type;
            playerState.deathTime = Date.now();
          }
        }
      }
    }
  },

  checkCollision(entity, hazard) {
    const ex = entity.x || 0;
    const ey = entity.y || 0;
    const ew = entity.width || 30;
    const eh = entity.height || 48;

    const hx = hazard.x || 0;
    const hy = hazard.y || 0;
    const hw = hazard.width || 32;
    const hh = hazard.height || 32;

    const shrink = 6;
    return (ex + shrink) < (hx + hw) &&
           (ex + ew - shrink) > hx &&
           (ey + shrink) < (hy + hh) &&
           (ey + eh - shrink) > hy;
  },

  getElementalInteraction(entityType, hazardType) {
    const interactions = {
      fireboy: {
        lava: 'immune',
        fire: 'immune',
        magma: 'immune',
        water: 'vulnerable',
        ice_water: 'vulnerable',
        pool: 'vulnerable',
        acid: 'vulnerable',
        goo: 'vulnerable',
        poison: 'vulnerable'
      },
      watergirl: {
        water: 'immune',
        ice_water: 'immune',
        pool: 'immune',
        lava: 'vulnerable',
        fire: 'vulnerable',
        magma: 'vulnerable',
        acid: 'vulnerable',
        goo: 'vulnerable',
        poison: 'vulnerable'
      }
    };

    return interactions[entityType]?.[hazardType] || 'neutral';
  },

  render(state, ctx) {
    const playerState = state.read('player_state');
    const positions = state.read('entity_positions');

    if (!playerState) return;

    if (positions && positions.fireboy) {
      this.renderFireboy(ctx, positions.fireboy, playerState.fireboy);
    }

    if (positions && positions.watergirl) {
      this.renderWatergirl(ctx, positions.watergirl, playerState.watergirl);
    }

    this.renderDeathEffects(ctx, playerState, positions);
  },

  renderFireboy(ctx, pos, state) {
    const x = pos.x || 0;
    const y = pos.y || 0;
    const w = pos.width || 30;
    const h = pos.height || 48;
    const frame = state.animFrame || 0;

    ctx.save();

    if (state.invulnerable && Math.floor(Date.now() / 80) % 2 === 0) {
      ctx.globalAlpha = 0.4;
    }

    if (!state.alive) {
      ctx.globalAlpha = 0.25;
    }

    const flamePhase = (Date.now() % 200) / 200;
    const flameWave = Math.sin(flamePhase * Math.PI * 2) * 3;

    ctx.fillStyle = '#FF6B1A';
    ctx.beginPath();
    ctx.ellipse(x + w/2, y + h * 0.65, w * 0.42, h * 0.32, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#FF8533';
    ctx.beginPath();
    ctx.moveTo(x + w * 0.15, y + h * 0.45);
    ctx.quadraticCurveTo(x + w * 0.3, y - 5 + flameWave, x + w * 0.5, y + h * 0.1);
    ctx.quadraticCurveTo(x + w * 0.7, y - 5 - flameWave, x + w * 0.85, y + h * 0.45);
    ctx.quadraticCurveTo(x + w * 0.7, y + h * 0.35, x + w * 0.5, y + h * 0.4);
    ctx.quadraticCurveTo(x + w * 0.3, y + h * 0.35, x + w * 0.15, y + h * 0.45);
    ctx.fill();

    ctx.fillStyle = '#FFB366';
    ctx.beginPath();
    ctx.ellipse(x + w/2, y + h * 0.35, w * 0.12, h * 0.12, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#FFF5E6';
    ctx.beginPath();
    ctx.arc(x + w * 0.38, y + h * 0.28, w * 0.06, 0, Math.PI * 2);
    ctx.arc(x + w * 0.62, y + h * 0.28, w * 0.06, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#1A0A00';
    ctx.beginPath();
    ctx.arc(x + w * 0.38, y + h * 0.28, w * 0.03, 0, Math.PI * 2);
    ctx.arc(x + w * 0.62, y + h * 0.28, w * 0.03, 0, Math.PI * 2);
    ctx.fill();

    const legSwing = Math.sin(frame * Math.PI / 2) * 4;
    ctx.fillStyle = '#CC4400';
    ctx.fillRect(x + w * 0.22, y + h * 0.88, w * 0.18, h * 0.12 + legSwing);
    ctx.fillRect(x + w * 0.60, y + h * 0.88, w * 0.18, h * 0.12 - legSwing);

    if (state.alive) {
      ctx.fillStyle = 'rgba(255, 150, 50, 0.15)';
      ctx.beginPath();
      ctx.ellipse(x + w/2, y + h * 0.5, w * 0.8, h * 0.5, 0, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  },

  renderWatergirl(ctx, pos, state) {
    const x = pos.x || 0;
    const y = pos.y || 0;
    const w = pos.width || 30;
    const h = pos.height || 48;
    const frame = state.animFrame || 0;

    ctx.save();

    if (state.invulnerable && Math.floor(Date.now() / 80) % 2 === 0) {
      ctx.globalAlpha = 0.4;
    }

    if (!state.alive) {
      ctx.globalAlpha = 0.25;
    }

    const shimmerPhase = (Date.now() % 300) / 300;
    const shimmer = Math.sin(shimmerPhase * Math.PI * 2) * 0.1;

    const bodyGrad = ctx.createLinearGradient(x, y, x + w, y + h);
    bodyGrad.addColorStop(0, '#4DA6FF');
    bodyGrad.addColorStop(0.5, '#3399FF');
    bodyGrad.addColorStop(1, '#1A8CFF');
    ctx.fillStyle = bodyGrad;
    ctx.beginPath();
    ctx.ellipse(x + w/2, y + h * 0.62, w * 0.38, h * 0.34, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#80C7FF';
    ctx.beginPath();
    ctx.moveTo(x + w * 0.5, y - 2);
    ctx.lineTo(x + w * 0.78, y + h * 0.35);
    ctx.lineTo(x + w * 0.5, y + h * 0.22);
    ctx.lineTo(x + w * 0.22, y + h * 0.35);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#B3DAFF';
    ctx.beginPath();
    ctx.moveTo(x + w * 0.5, y + h * 0.05);
    ctx.lineTo(x + w * 0.62, y + h * 0.25);
    ctx.lineTo(x + w * 0.5, y + h * 0.18);
    ctx.lineTo(x + w * 0.38, y + h * 0.25);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#CCEEFF';
    ctx.beginPath();
    ctx.ellipse(x + w/2, y + h * 0.32, w * 0.22, w * 0.16, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath();
    ctx.arc(x + w * 0.40, y + h * 0.30, w * 0.055, 0, Math.PI * 2);
    ctx.arc(x + w * 0.60, y + h * 0.30, w * 0.055, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#001A33';
    ctx.beginPath();
    ctx.arc(x + w * 0.40, y + h * 0.30, w * 0.028, 0, Math.PI * 2);
    ctx.arc(x + w * 0.60, y + h * 0.30, w * 0.028, 0, Math.PI * 2);
    ctx.fill();

    const legSwing = Math.sin(frame * Math.PI / 2) * 4;
    ctx.fillStyle = '#1A6BB8';
    ctx.fillRect(x + w * 0.25, y + h * 0.88, w * 0.18, h * 0.12 + legSwing);
    ctx.fillRect(x + w * 0.57, y + h * 0.88, w * 0.18, h * 0.12 - legSwing);

    if (state.alive) {
      ctx.fillStyle = 'rgba(100, 180, 255, 0.12)';
      ctx.beginPath();
      ctx.ellipse(x + w/2, y + h * 0.5, w * 0.75, h * 0.45, 0, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  },

  renderDeathEffects(ctx, playerState, positions) {
    if (!positions) return;

    if (!playerState.fireboy.alive && playerState.fireboy.deathReason === 'water') {
      const pos = positions.fireboy;
      if (pos) {
        ctx.save();
        const time = Date.now() - (playerState.fireboy.deathTime || 0);
        const progress = Math.min(time / 1000, 1);

        ctx.globalAlpha = 1 - progress;
        ctx.fillStyle = '#99CCFF';
        for (let i = 0; i < 5; i++) {
          const angle = (i / 5) * Math.PI * 2 + time / 200;
          const radius = progress * 30;
          const px = pos.x + pos.width/2 + Math.cos(angle) * radius;
          const py = pos.y + pos.height/2 + Math.sin(angle) * radius;
          ctx.beginPath();
          ctx.arc(px, py, 4 + Math.random() * 3, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.restore();
      }
    }

    if (!playerState.watergirl.alive && (playerState.watergirl.deathReason === 'lava' || playerState.watergirl.deathReason === 'fire')) {
      const pos = positions.watergirl;
      if (pos) {
        ctx.save();
        const time = Date.now() - (playerState.watergirl.deathTime || 0);
        const progress = Math.min(time / 1000, 1);

        ctx.globalAlpha = 1 - progress;
        ctx.fillStyle = '#FF6633';
        for (let i = 0; i < 6; i++) {
          const angle = (i / 6) * Math.PI * 2 + time / 150;
          const radius = progress * 25;
          const px = pos.x + pos.width/2 + Math.cos(angle) * radius;
          const py = pos.y + pos.height/2 + Math.sin(angle) * radius - progress * 20;
          ctx.beginPath();
          ctx.arc(px, py, 5 + Math.random() * 4, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.restore();
      }
    }
  }
};

export default ElementalAffinity;

const ElementalAffinity = {
  name: 'ElementalAffinity',

  init(state) {
    state.write('player_state', {
      fireboy: {
        alive: true,
        health: 100,
        invulnerable: false,
        invulnerableTimer: 0,
        deathReason: null,
        animFrame: 0,
        walkTime: 0,
        facingRight: true
      },
      watergirl: {
        alive: true,
        health: 100,
        invulnerable: false,
        invulnerableTimer: 0,
        deathReason: null,
        animFrame: 0,
        walkTime: 0,
        facingRight: true
      },
      gameOver: false,
      winner: null
    });
  },

  update(state, dt) {
    const positions = state.read('entity_positions');
    const hazards = state.read('hazard_zones');
    const playerState = state.read('player_state');

    if (!playerState) return;

    const newState = JSON.parse(JSON.stringify(playerState));

    // Update invulnerability timers
    if (newState.fireboy.invulnerableTimer > 0) {
      newState.fireboy.invulnerableTimer -= dt;
      if (newState.fireboy.invulnerableTimer <= 0) {
        newState.fireboy.invulnerable = false;
        newState.fireboy.invulnerableTimer = 0;
      }
    }

    if (newState.watergirl.invulnerableTimer > 0) {
      newState.watergirl.invulnerableTimer -= dt;
      if (newState.watergirl.invulnerableTimer <= 0) {
        newState.watergirl.invulnerable = false;
        newState.watergirl.invulnerableTimer = 0;
      }
    }

    // Update walk animation
    if (positions) {
      if (positions.fireboy && positions.fireboy.velocityX !== 0) {
        newState.fireboy.walkTime += dt;
        newState.fireboy.animFrame = Math.floor(newState.fireboy.walkTime * 8) % 4;
        newState.fireboy.facingRight = positions.fireboy.velocityX > 0;
      }
      if (positions.watergirl && positions.watergirl.velocityX !== 0) {
        newState.watergirl.walkTime += dt;
        newState.watergirl.animFrame = Math.floor(newState.watergirl.walkTime * 8) % 4;
        newState.watergirl.facingRight = positions.watergirl.velocityX > 0;
      }
    }

    // Process hazard interactions
    if (positions && hazards) {
      if (newState.fireboy.alive && positions.fireboy) {
        this.checkHazardInteraction(positions.fireboy, hazards, 'fireboy', newState, dt);
      }
      if (newState.watergirl.alive && positions.watergirl) {
        this.checkHazardInteraction(positions.watergirl, hazards, 'watergirl', newState, dt);
      }
    }

    // Check game over conditions
    if (!newState.fireboy.alive && !newState.gameOver) {
      newState.gameOver = true;
      newState.winner = 'watergirl';
    }
    if (!newState.watergirl.alive && !newState.gameOver) {
      newState.gameOver = true;
      newState.winner = 'fireboy';
    }
    if (!newState.fireboy.alive && !newState.watergirl.alive) {
      newState.gameOver = true;
      newState.winner = 'none';
    }

    state.write('player_state', newState);
  },

  checkHazardInteraction(entity, hazards, playerName, state, dt) {
    if (!hazards || !entity) return;

    const player = state[playerName];
    if (!player.alive || player.invulnerable) return;

    const entityBounds = {
      left: entity.x,
      right: entity.x + (entity.width || 24),
      top: entity.y,
      bottom: entity.y + (entity.height || 32)
    };

    const isFireboy = playerName === 'fireboy';

    for (const hazard of hazards) {
      const hazardBounds = {
        left: hazard.x,
        right: hazard.x + (hazard.width || 32),
        top: hazard.y,
        bottom: hazard.y + (hazard.height || 32)
      };

      // Check collision
      if (this.boundsOverlap(entityBounds, hazardBounds)) {
        const hazardType = hazard.type || hazard.hazardType;

        // Fireboy: immune to lava/fire, vulnerable to water
        // Watergirl: immune to water, vulnerable to lava/fire
        if (isFireboy) {
          if (hazardType === 'water' || hazardType === 'pool_water') {
            // Instant death for fireboy in water
            player.health = 0;
            player.alive = false;
            player.deathReason = 'water';
            return;
          }
          // Fireboy is immune to lava
        } else {
          if (hazardType === 'lava' || hazardType === 'fire' || hazardType === 'pool_lava') {
            // Instant death for watergirl in lava
            player.health = 0;
            player.alive = false;
            player.deathReason = 'lava';
            return;
          }
          // Watergirl is immune to water
        }

        // Handle other hazard types (green goo kills both)
        if (hazardType === 'goo' || hazardType === 'acid' || hazardType === 'green_goo') {
          player.health = 0;
          player.alive = false;
          player.deathReason = 'goo';
          return;
        }
      }
    }
  },

  boundsOverlap(a, b) {
    return a.left < b.right &&
           a.right > b.left &&
           a.top < b.bottom &&
           a.bottom > b.top;
  },

  render(state, ctx) {
    const positions = state.read('entity_positions');
    const playerState = state.read('player_state');

    if (!positions || !playerState) return;

    // Render Fireboy
    if (positions.fireboy && playerState.fireboy.alive) {
      this.renderCharacter(ctx, positions.fireboy, 'fireboy', playerState.fireboy);
    }

    // Render Watergirl
    if (positions.watergirl && playerState.watergirl.alive) {
      this.renderCharacter(ctx, positions.watergirl, 'watergirl', playerState.watergirl);
    }
  },

  renderCharacter(ctx, entity, type, playerData) {
    const x = entity.x;
    const y = entity.y;
    const width = entity.width || 24;
    const height = entity.height || 32;
    const isFireboy = type === 'fireboy';
    const animFrame = playerData.animFrame || 0;
    const facingRight = playerData.facingRight !== false;
    const invulnerable = playerData.invulnerable;

    // Flicker when invulnerable
    if (invulnerable && Math.floor(Date.now() / 100) % 2 === 0) {
      ctx.globalAlpha = 0.5;
    }

    ctx.save();

    if (!facingRight) {
      ctx.translate(x + width, y);
      ctx.scale(-1, 1);
      ctx.translate(-x, -y);
    }

    // Walking bob animation
    const bobOffset = animFrame % 2 === 1 ? -2 : 0;
    const legOffset = animFrame % 2 === 1 ? 3 : -3;

    if (isFireboy) {
      // Fireboy - Orange flame sprite
      // Body
      const gradient = ctx.createLinearGradient(x, y + bobOffset, x + width, y + height + bobOffset);
      gradient.addColorStop(0, '#ff6b00');
      gradient.addColorStop(0.5, '#ff4500');
      gradient.addColorStop(1, '#cc3300');

      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.ellipse(x + width/2, y + height - 10 + bobOffset, width/2 - 2, height/2 - 4, 0, 0, Math.PI * 2);
      ctx.fill();

      // Flame head
      ctx.fillStyle = '#ff8c00';
      ctx.beginPath();
      ctx.moveTo(x + width/2, y + bobOffset);
      ctx.lineTo(x + width - 2, y + 14 + bobOffset);
      ctx.lineTo(x + width/2, y + 8 + bobOffset);
      ctx.lineTo(x + 2, y + 14 + bobOffset);
      ctx.closePath();
      ctx.fill();

      // Inner flame
      ctx.fillStyle = '#ffcc00';
      ctx.beginPath();
      ctx.moveTo(x + width/2, y + 4 + bobOffset);
      ctx.lineTo(x + width - 6, y + 12 + bobOffset);
      ctx.lineTo(x + 6, y + 12 + bobOffset);
      ctx.closePath();
      ctx.fill();

      // Eyes
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(x + width/2 - 4, y + 14 + bobOffset, 3, 0, Math.PI * 2);
      ctx.arc(x + width/2 + 4, y + 14 + bobOffset, 3, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#000000';
      ctx.beginPath();
      ctx.arc(x + width/2 - 4, y + 14 + bobOffset, 1.5, 0, Math.PI * 2);
      ctx.arc(x + width/2 + 4, y + 14 + bobOffset, 1.5, 0, Math.PI * 2);
      ctx.fill();

      // Legs with walk animation
      ctx.fillStyle = '#ff4500';
      ctx.fillRect(x + width/2 - 6 + legOffset, y + height - 6, 4, 6);
      ctx.fillRect(x + width/2 + 2 - legOffset, y + height - 6, 4, 6);

    } else {
      // Watergirl - Blue ice/frost sprite
      // Body
      const gradient = ctx.createLinearGradient(x, y + bobOffset, x + width, y + height + bobOffset);
      gradient.addColorStop(0, '#00bfff');
      gradient.addColorStop(0.5, '#1e90ff');
      gradient.addColorStop(1, '#0066cc');

      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.ellipse(x + width/2, y + height - 10 + bobOffset, width/2 - 2, height/2 - 4, 0, 0, Math.PI * 2);
      ctx.fill();

      // Ice crystal head
      ctx.fillStyle = '#87ceeb';
      ctx.beginPath();
      ctx.moveTo(x + width/2, y - 2 + bobOffset);
      ctx.lineTo(x + width - 2, y + 10 + bobOffset);
      ctx.lineTo(x + width/2, y + 18 + bobOffset);
      ctx.lineTo(x + 2, y + 10 + bobOffset);
      ctx.closePath();
      ctx.fill();

      // Inner crystal
      ctx.fillStyle = '#b0e0e6';
      ctx.beginPath();
      ctx.moveTo(x + width/2, y + 2 + bobOffset);
      ctx.lineTo(x + width - 6, y + 10 + bobOffset);
      ctx.lineTo(x + 6, y + 10 + bobOffset);
      ctx.closePath();
      ctx.fill();

      // Eyes
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(x + width/2 - 4, y + 12 + bobOffset, 3, 0, Math.PI * 2);
      ctx.arc(x + width/2 + 4, y + 12 + bobOffset, 3, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#000033';
      ctx.beginPath();
      ctx.arc(x + width/2 - 4, y + 12 + bobOffset, 1.5, 0, Math.PI * 2);
      ctx.arc(x + width/2 + 4, y + 12 + bobOffset, 1.5, 0, Math.PI * 2);
      ctx.fill();

      // Legs with walk animation
      ctx.fillStyle = '#1e90ff';
      ctx.fillRect(x + width/2 - 6 + legOffset, y + height - 6, 4, 6);
      ctx.fillRect(x + width/2 + 2 - legOffset, y + height - 6, 4, 6);

      // Sparkle effect
      ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
      const sparkleTime = Date.now() / 200;
      ctx.beginPath();
      ctx.arc(x + 4 + Math.sin(sparkleTime) * 2, y + 6 + bobOffset, 1.5, 0, Math.PI * 2);
      ctx.arc(x + width - 4 + Math.cos(sparkleTime) * 2, y + 8 + bobOffset, 1, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
    ctx.globalAlpha = 1;
  }
};

