const GemCollector = {
  name: 'GemCollector',

  init(state) {
    state.write('gem_collection', {
      collectedGems: [],
      fireboyCount: 0,
      totalGems: 0,
      pickupRadius: 28,
      pickupEffects: []
    });
  },

  update(state, dt) {
    const entityPositions = state.read('entity_positions');
    const gemCollection = state.read('gem_collection');

    if (!entityPositions || !gemCollection) return;

    const fireboy = entityPositions.fireboy || entityPositions.Fireboy;
    const gems = entityPositions.gems || [];

    if (!fireboy) return;

    let updated = false;
    const newCollected = [...gemCollection.collectedGems];
    const newEffects = gemCollection.pickupEffects.filter(e => e.life > 0);

    gems.forEach((gem, index) => {
      const gemId = gem.id !== undefined ? gem.id : `gem_${index}`;

      if (gem.type !== 'red' && gem.type !== 'fire_gem') return;
      if (newCollected.includes(gemId)) return;

      const dx = fireboy.x - gem.x;
      const dy = fireboy.y - gem.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (distance <= gemCollection.pickupRadius) {
        newCollected.push(gemId);
        newEffects.push({
          x: gem.x,
          y: gem.y,
          life: 1.0
        });
        updated = true;
      }
    });

    newEffects.forEach(e => {
      e.life -= dt * 2;
    });

    if (updated || newEffects.some(e => e.life > 0) !== gemCollection.pickupEffects.some(e => e.life > 0)) {
      state.write('gem_collection', {
        collectedGems: newCollected,
        fireboyCount: newCollected.length,
        totalGems: gems.filter(g => g.type === 'red' || g.type === 'fire_gem').length,
        pickupRadius: gemCollection.pickupRadius,
        pickupEffects: newEffects.filter(e => e.life > 0)
      });
    }
  },

  render(state, ctx) {
    const entityPositions = state.read('entity_positions');
    const gemCollection = state.read('gem_collection');

    if (!entityPositions || !gemCollection) return;

    const gems = entityPositions.gems || [];
    const fireboy = entityPositions.fireboy || entityPositions.Fireboy;

    gems.forEach((gem, index) => {
      const gemId = gem.id !== undefined ? gem.id : `gem_${index}`;

      if (gem.type !== 'red' && gem.type !== 'fire_gem') return;
      if (gemCollection.collectedGems.includes(gemId)) return;

      ctx.save();
      ctx.translate(gem.x, gem.y);

      const time = Date.now() / 1000;
      const floatOffset = Math.sin(time * 3 + index) * 3;
      const pulse = 1 + Math.sin(time * 4 + index) * 0.15;
      ctx.translate(0, floatOffset);
      ctx.scale(pulse, pulse);

      ctx.shadowColor = '#ff2222';
      ctx.shadowBlur = 15 + Math.sin(time * 5) * 5;

      ctx.beginPath();
      ctx.moveTo(0, -14);
      ctx.lineTo(11, 0);
      ctx.lineTo(0, 14);
      ctx.lineTo(-11, 0);
      ctx.closePath();

      const gradient = ctx.createLinearGradient(-11, -14, 11, 14);
      gradient.addColorStop(0, '#ff4444');
      gradient.addColorStop(0.3, '#ff0000');
      gradient.addColorStop(0.7, '#cc0000');
      gradient.addColorStop(1, '#990000');
      ctx.fillStyle = gradient;
      ctx.fill();

      ctx.strokeStyle = '#ff6666';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(-2, -7);
      ctx.lineTo(4, -1);
      ctx.lineTo(0, 4);
      ctx.lineTo(-5, -1);
      ctx.closePath();
      ctx.fillStyle = 'rgba(255, 200, 200, 0.5)';
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(-1, -4);
      ctx.lineTo(1, -2);
      ctx.lineTo(-1, 0);
      ctx.closePath();
      ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
      ctx.fill();

      ctx.restore();
    });

    gemCollection.pickupEffects.forEach(effect => {
      ctx.save();
      ctx.globalAlpha = effect.life;
      ctx.translate(effect.x, effect.y);

      const rings = 3;
      for (let i = 0; i < rings; i++) {
        const ringProgress = 1 - effect.life;
        const ringRadius = 20 + ringProgress * 40 + i * 15;
        const ringAlpha = effect.life * (1 - i / rings);

        ctx.beginPath();
        ctx.arc(0, 0, ringRadius, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(255, 100, 50, ${ringAlpha})`;
        ctx.lineWidth = 3 - i;
        ctx.stroke();
      }

      const particles = 8;
      for (let i = 0; i < particles; i++) {
        const angle = (i / particles) * Math.PI * 2;
        const dist = (1 - effect.life) * 50;
        const px = Math.cos(angle) * dist;
        const py = Math.sin(angle) * dist;

        ctx.beginPath();
        ctx.arc(px, py, 3 * effect.life, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255, 150, 50, ${effect.life})`;
        ctx.fill();
      }

      ctx.restore();
    });

    if (fireboy && gemCollection.fireboyCount > 0) {
      ctx.save();
      ctx.font = 'bold 14px Arial';
      ctx.textAlign = 'center';
      ctx.fillStyle = '#ffcc00';
      ctx.shadowColor = '#ff6600';
      ctx.shadowBlur = 4;

      const counterY = fireboy.y - (fireboy.height || 40) - 10;
      ctx.fillText(`+${gemCollection.fireboyCount}`, fireboy.x, counterY);
      ctx.restore();
    }
  }
};

