const MovementController = {
  name: 'MovementController',

  keys: {},

  init(state) {
    const initialPositions = {
      fireboy: {
        x: 100,
        y: 300,
        vx: 0,
        vy: 0,
        width: 32,
        height: 48,
        onGround: false,
        facing: 1,
        animFrame: 0,
        animTimer: 0,
        isMoving: false
      },
      watergirl: {
        x: 150,
        y: 300,
        vx: 0,
        vy: 0,
        width: 32,
        height: 48,
        onGround: false,
        facing: 1,
        animFrame: 0,
        animTimer: 0,
        isMoving: false
      }
    };

    state.write('entity_positions', initialPositions);

    window.addEventListener('keydown', (e) => {
      this.keys[e.key.toLowerCase()] = true;
      if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', 'w', 'a', 's', 'd'].includes(e.key.toLowerCase())) {
        e.preventDefault();
      }
    });

    window.addEventListener('keyup', (e) => {
      this.keys[e.key.toLowerCase()] = false;
    });
  },

  update(state, dt) {
    const playerState = state.read('player_state');
    const positions = state.read('entity_positions');

    if (!positions) return;

    const GRAVITY = 980;
    const MOVE_SPEED = 180;
    const ACCELERATION = 1200;
    const FRICTION = 0.88;
    const JUMP_FORCE = -420;
    const MAX_FALL_SPEED = 600;

    const fireboyInput = {
      left: this.keys['arrowleft'],
      right: this.keys['arrowright'],
      jump: this.keys['arrowup']
    };

    const watergirlInput = {
      left: this.keys['a'],
      right: this.keys['d'],
      jump: this.keys['w']
    };

    this.updateCharacter(positions.fireboy, fireboyInput, dt, GRAVITY, MOVE_SPEED, ACCELERATION, FRICTION, JUMP_FORCE, MAX_FALL_SPEED);
    this.updateCharacter(positions.watergirl, watergirlInput, dt, GRAVITY, MOVE_SPEED, ACCELERATION, FRICTION, JUMP_FORCE, MAX_FALL_SPEED);

    if (playerState && playerState.levelGround !== undefined) {
      const groundY = playerState.levelGround || 450;
      this.applyGroundConstraint(positions.fireboy, groundY);
      this.applyGroundConstraint(positions.watergirl, groundY);
    } else {
      this.applyGroundConstraint(positions.fireboy, 450);
      this.applyGroundConstraint(positions.watergirl, 450);
    }

    state.write('entity_positions', positions);
  },

  updateCharacter(entity, input, dt, gravity, moveSpeed, accel, friction, jumpForce, maxFallSpeed) {
    entity.isMoving = false;

    if (input.left) {
      entity.vx -= accel * dt;
      if (entity.vx < -moveSpeed) entity.vx = -moveSpeed;
      entity.facing = -1;
      entity.isMoving = true;
    } else if (input.right) {
      entity.vx += accel * dt;
      if (entity.vx > moveSpeed) entity.vx = moveSpeed;
      entity.facing = 1;
      entity.isMoving = true;
    } else {
      entity.vx *= friction;
      if (Math.abs(entity.vx) < 5) entity.vx = 0;
    }

    if (input.jump && entity.onGround) {
      entity.vy = jumpForce;
      entity.onGround = false;
    }

    entity.vy += gravity * dt;
    if (entity.vy > maxFallSpeed) entity.vy = maxFallSpeed;

    entity.x += entity.vx * dt;
    entity.y += entity.vy * dt;

    if (entity.isMoving && entity.onGround) {
      entity.animTimer += dt;
      if (entity.animTimer > 0.08) {
        entity.animTimer = 0;
        entity.animFrame = (entity.animFrame + 1) % 4;
      }
    } else if (!entity.onGround) {
      entity.animFrame = 2;
    } else {
      entity.animFrame = 0;
      entity.animTimer = 0;
    }
  },

  applyGroundConstraint(entity, groundY) {
    if (entity.y + entity.height > groundY) {
      entity.y = groundY - entity.height;
      entity.vy = 0;
      entity.onGround = true;
    }

    if (entity.x < 0) entity.x = 0;
    if (entity.x > 768) entity.x = 768;
  },

  render(state, ctx) {
    const positions = state.read('entity_positions');
    if (!positions) return;

    this.renderFireboy(ctx, positions.fireboy);
    this.renderWatergirl(ctx, positions.watergirl);
  },

  renderFireboy(ctx, entity) {
    ctx.save();
    ctx.translate(entity.x + entity.width / 2, entity.y + entity.height);
    ctx.scale(entity.facing, 1);

    const bobY = entity.isMoving ? Math.sin(entity.animFrame * Math.PI / 2) * 2 : 0;
    const legOffset = entity.isMoving ? Math.sin(entity.animFrame * Math.PI / 2) * 6 : 0;

    ctx.fillStyle = '#ff5500';
    ctx.fillRect(-4 + legOffset, -12, 6, 12);
    ctx.fillRect(-2 - legOffset, -12, 6, 12);

    ctx.fillStyle = '#ff6600';
    ctx.fillRect(-10, -38 + bobY, 20, 26);

    ctx.fillStyle = '#ff7700';
    ctx.beginPath();
    ctx.arc(0, -44 + bobY, 12, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#ffcc00';
    for (let i = 0; i < 3; i++) {
      const flicker = Math.sin(Date.now() / 100 + i * 2) * 3;
      ctx.beginPath();
      ctx.arc(-8 + i * 8, -54 + bobY + flicker, 4 - i * 0.5, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.fillStyle = '#fff';
    ctx.fillRect(-6, -48 + bobY, 4, 5);
    ctx.fillRect(2, -48 + bobY, 4, 5);

    ctx.fillStyle = '#000';
    ctx.fillRect(-5, -47 + bobY, 2, 3);
    ctx.fillRect(3, -47 + bobY, 2, 3);

    ctx.restore();
  },

  renderWatergirl(ctx, entity) {
    ctx.save();
    ctx.translate(entity.x + entity.width / 2, entity.y + entity.height);
    ctx.scale(entity.facing, 1);

    const bobY = entity.isMoving ? Math.sin(entity.animFrame * Math.PI / 2) * 2 : 0;
    const legOffset = entity.isMoving ? Math.sin(entity.animFrame * Math.PI / 2) * 6 : 0;

    ctx.fillStyle = '#0088cc';
    ctx.fillRect(-4 + legOffset, -12, 6, 12);
    ctx.fillRect(-2 - legOffset, -12, 6, 12);

    ctx.fillStyle = '#00aaff';
    ctx.fillRect(-10, -38 + bobY, 20, 26);

    ctx.fillStyle = '#33bbff';
    ctx.beginPath();
    ctx.arc(0, -44 + bobY, 12, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#88ddff';
    for (let i = 0; i < 4; i++) {
      const spark = Math.cos(Date.now() / 150 + i * 1.5) * 2;
      ctx.beginPath();
      ctx.arc(-9 + i * 6, -54 + bobY + spark, 3, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.fillStyle = '#fff';
    ctx.fillRect(-6, -48 + bobY, 4, 5);
    ctx.fillRect(2, -48 + bobY, 4, 5);

    ctx.fillStyle = '#003366';
    ctx.fillRect(-5, -47 + bobY, 2, 3);
    ctx.fillRect(3, -47 + bobY, 2, 3);

    ctx.restore();
  }
};

