const MovementController = {
  name: 'MovementController',

  keys: {},

  init(state) {
    const initialPositions = {
      fireboy: {
        x: 100,
        y: 300,
        vx: 0,
        vy: 0,
        width: 32,
        height: 48,
        onGround: false,
        facing: 1,
        animFrame: 0,
        animTimer: 0,
        isMoving: false
      },
      watergirl: {
        x: 150,
        y: 300,
        vx: 0,
        vy: 0,
        width: 32,
        height: 48,
        onGround: false,
        facing: 1,
        animFrame: 0,
        animTimer: 0,
        isMoving: false
      }
    };

    state.write('entity_positions', initialPositions);

    window.addEventListener('keydown', (e) => {
      this.keys[e.key.toLowerCase()] = true;
      if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', 'w', 'a', 's', 'd'].includes(e.key.toLowerCase())) {
        e.preventDefault();
      }
    });

    window.addEventListener('keyup', (e) => {
      this.keys[e.key.toLowerCase()] = false;
    });
  },

  update(state, dt) {
    const positions = state.read('entity_positions');
    if (!positions) return;

    const GRAVITY = 980;
    const MOVE_SPEED = 180;
    const ACCELERATION = 1200;
    const FRICTION = 0.88;
    const JUMP_FORCE = -420;
    const MAX_FALL_SPEED = 600;
    const GROUND_Y = 450;

    const fireboyInput = {
      left: this.keys['arrowleft'],
      right: this.keys['arrowright'],
      jump: this.keys['arrowup']
    };

    const watergirlInput = {
      left: this.keys['a'],
      right: this.keys['d'],
      jump: this.keys['w']
    };

    this.updateEntity(positions.fireboy, fireboyInput, dt, GRAVITY, MOVE_SPEED, ACCELERATION, FRICTION, JUMP_FORCE, MAX_FALL_SPEED, GROUND_Y);
    this.updateEntity(positions.watergirl, watergirlInput, dt, GRAVITY, MOVE_SPEED, ACCELERATION, FRICTION, JUMP_FORCE, MAX_FALL_SPEED, GROUND_Y);

    state.write('entity_positions', positions);
  },

  updateEntity(entity, input, dt, gravity, moveSpeed, acceleration, friction, jumpForce, maxFallSpeed, groundY) {
    if (input.left) {
      entity.vx -= acceleration * dt;
      entity.facing = -1;
      entity.isMoving = true;
    } else if (input.right) {
      entity.vx += acceleration * dt;
      entity.facing = 1;
      entity.isMoving = true;
    } else {
      entity.isMoving = false;
    }

    entity.vx = Math.max(-moveSpeed, Math.min(moveSpeed, entity.vx));

    if (!input.left && !input.right) {
      entity.vx *= friction;
    }

    if (input.jump && entity.onGround) {
      entity.vy = jumpForce;
      entity.onGround = false;
    }

    entity.vy += gravity * dt;
    entity.vy = Math.min(entity.vy, maxFallSpeed);

    entity.x += entity.vx * dt;
    entity.y += entity.vy * dt;

    if (entity.y >= groundY - entity.height) {
      entity.y = groundY - entity.height;
      entity.vy = 0;
      entity.onGround = true;
    }

    if (entity.x < 0) entity.x = 0;
    if (entity.x > 768) entity.x = 768;

    if (entity.isMoving && entity.onGround) {
      entity.animTimer += dt;
      if (entity.animTimer > 0.1) {
        entity.animTimer = 0;
        entity.animFrame = (entity.animFrame + 1) % 4;
      }
    } else {
      entity.animFrame = 0;
      entity.animTimer = 0;
    }
  },

  render(state, ctx) {
    const positions = state.read('entity_positions');
    if (!positions) return;

    this.drawCharacter(ctx, positions.fireboy, '#ff6600', '#ffaa00', '#ff3300', 'fireboy');
    this.drawCharacter(ctx, positions.watergirl, '#0088ff', '#00ccff', '#88ddff', 'watergirl');
  },

  drawCharacter(ctx, entity, primaryColor, secondaryColor, accentColor, type) {
    ctx.save();
    ctx.translate(entity.x + entity.width / 2, entity.y + entity.height / 2);
    ctx.scale(entity.facing, 1);
    ctx.translate(-entity.width / 2, -entity.height / 2);

    ctx.fillStyle = primaryColor;
    ctx.fillRect(4, 16, 24, 24);

    ctx.fillStyle = secondaryColor;
    ctx.beginPath();
    ctx.arc(16, 12, 10, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(9, 9, 4, 4);
    ctx.fillRect(18, 9, 4, 4);

    ctx.fillStyle = '#222222';
    ctx.fillRect(11, 11, 2, 2);
    ctx.fillRect(20, 11, 2, 2);

    const legOffset = Math.sin(entity.animFrame * Math.PI / 2) * 3;
    ctx.fillStyle = primaryColor;
    ctx.fillRect(6, 40, 8, 8 + legOffset);
    ctx.fillRect(18, 40, 8, 8 - legOffset);

    if (type === 'fireboy') {
      ctx.fillStyle = accentColor;
      const flameTime = Date.now() / 100;
      ctx.beginPath();
      ctx.moveTo(8, 6);
      ctx.quadraticCurveTo(10, -4 + Math.sin(flameTime) * 3, 16, -6 + Math.sin(flameTime) * 4);
      ctx.quadraticCurveTo(22, -4 + Math.sin(flameTime + 1) * 3, 24, 6);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#ffff00';
      ctx.beginPath();
      ctx.moveTo(11, 4);
      ctx.quadraticCurveTo(13, -2 + Math.sin(flameTime + 0.5) * 2, 16, -3 + Math.sin(flameTime + 0.5) * 3);
      ctx.quadraticCurveTo(19, -2 + Math.sin(flameTime + 1.5) * 2, 21, 4);
      ctx.closePath();
      ctx.fill();
    } else {
      ctx.fillStyle = accentColor;
      const iceTime = Date.now() / 150;

      ctx.beginPath();
      ctx.moveTo(8, 4);
      ctx.lineTo(10, -4 + Math.sin(iceTime) * 2);
      ctx.lineTo(12, 4);
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(14, 2);
      ctx.lineTo(16, -6 + Math.sin(iceTime + 1) * 2);
      ctx.lineTo(18, 2);
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(20, 4);
      ctx.lineTo(22, -4 + Math.sin(iceTime + 2) * 2);
      ctx.lineTo(24, 4);
      ctx.fill();
    }

    ctx.restore();
  }
};

