const collision_detector = {
  name: 'collision_detector',

  collisions: null,
  tileSize: 32,
  entityWidth: 28,
  entityHeight: 44,

  init(state) {
    this.collisions = {
      fireboy: {
        tiles: { top: null, bottom: null, left: null, right: null },
        hazards: [],
        mechanisms: [],
        gems: [],
        exit: null,
        grounded: false,
        dead: false,
        deathCause: null
      },
      watergirl: {
        tiles: { top: null, bottom: null, left: null, right: null },
        hazards: [],
        mechanisms: [],
        gems: [],
        exit: null,
        grounded: false,
        dead: false,
        deathCause: null
      }
    };
  },

  update(state, dt) {
    const positions = state.read('entity_positions');
    const velocities = state.read('velocity_vectors');
    const tileLayout = state.read('tile_layout');
    const hazardZones = state.read('hazard_zones');
    const mechanismState = state.read('mechanism_state');
    const gemCollection = state.read('gem_collection');

    this.resetCollisions();

    if (!positions) return;

    if (positions.fireboy) {
      this.detectEntityCollisions(
        'fireboy',
        positions.fireboy,
        velocities?.fireboy || { vx: 0, vy: 0 },
        tileLayout,
        hazardZones,
        mechanismState,
        gemCollection
      );
    }

    if (positions.watergirl) {
      this.detectEntityCollisions(
        'watergirl',
        positions.watergirl,
        velocities?.watergirl || { vx: 0, vy: 0 },
        tileLayout,
        hazardZones,
        mechanismState,
        gemCollection
      );
    }

    this.checkHazardDamage();
  },

  resetCollisions() {
    this.collisions.fireboy = {
      tiles: { top: null, bottom: null, left: null, right: null },
      hazards: [],
      mechanisms: [],
      gems: [],
      exit: null,
      grounded: false,
      dead: false,
      deathCause: null
    };
    this.collisions.watergirl = {
      tiles: { top: null, bottom: null, left: null, right: null },
      hazards: [],
      mechanisms: [],
      gems: [],
      exit: null,
      grounded: false,
      dead: false,
      deathCause: null
    };
  },

  detectEntityCollisions(entityName, pos, vel, tiles, hazards, mechanisms, gems) {
    const collision = this.collisions[entityName];
    const halfW = this.entityWidth / 2;
    const halfH = this.entityHeight / 2;

    const bounds = {
      left: pos.x - halfW,
      right: pos.x + halfW,
      top: pos.y - this.entityHeight,
      bottom: pos.y
    };

    // Tile collisions
    if (tiles && tiles.solidTiles) {
      this.checkTileCollisions(entityName, bounds, vel, tiles.solidTiles);
    }

    // Check platforms (mechanisms)
    if (tiles && tiles.platforms) {
      this.checkPlatformCollisions(entityName, bounds, vel, tiles.platforms);
    }

    // Hazard collisions
    if (hazards && Array.isArray(hazards)) {
      for (const hazard of hazards) {
        if (this.boundsOverlap(bounds, hazard)) {
          collision.hazards.push(hazard);
        }
      }
    }

    // Mechanism collisions (buttons, levers)
    if (mechanisms && Array.isArray(mechanisms)) {
      for (const mech of mechanisms) {
        if (mech.type === 'button' || mech.type === 'lever' || mech.type === 'door') {
          if (this.boundsOverlap(bounds, mech)) {
            collision.mechanisms.push(mech);
          }
        }
      }
    }

    // Gem collisions
    if (gems && Array.isArray(gems)) {
      for (const gem of gems) {
        if (!gem.collected && this.boundsOverlap(bounds, gem)) {
          // Check if gem matches character type
          const isMatch = (entityName === 'fireboy' && gem.type === 'fire') ||
                         (entityName === 'watergirl' && gem.type === 'water');
          if (isMatch || !gem.type) {
            collision.gems.push(gem);
          }
        }
      }
    }

    // Exit collision
    if (tiles && tiles.exit) {
      const exit = tiles.exit;
      const exitBounds = {
        left: exit.x,
        right: exit.x + (exit.width || this.tileSize),
        top: exit.y,
        bottom: exit.y + (exit.height || this.tileSize * 2)
      };
      if (this.boundsOverlap(bounds, exitBounds)) {
        collision.exit = exit;
      }
    }
  },

  checkTileCollisions(entityName, bounds, vel, solidTiles) {
    const collision = this.collisions[entityName];

    for (const tile of solidTiles) {
      const tileBounds = {
        left: tile.x,
        right: tile.x + this.tileSize,
        top: tile.y,
        bottom: tile.y + this.tileSize
      };

      if (!this.boundsOverlap(bounds, tileBounds)) continue;

      const overlapX = Math.min(bounds.right - tileBounds.left, tileBounds.right - bounds.left);
      const overlapY = Math.min(bounds.bottom - tileBounds.top, tileBounds.bottom - bounds.top);

      // Bottom collision (landing on tile)
      if (overlapY < overlapX && vel.vy >= 0 && bounds.bottom > tileBounds.top && bounds.top < tileBounds.top) {
        collision.tiles.bottom = tile;
        collision.grounded = true;
      }
      // Top collision (hitting ceiling)
      else if (overlapY < overlapX && vel.vy <= 0 && bounds.top < tileBounds.bottom && bounds.bottom > tileBounds.bottom) {
        collision.tiles.top = tile;
      }
      // Side collisions
      else if (overlapX < overlapY) {
        if (vel.vx > 0 && bounds.right > tileBounds.left && bounds.left < tileBounds.left) {
          collision.tiles.right = tile;
        } else if (vel.vx < 0 && bounds.left < tileBounds.right && bounds.right > tileBounds.right) {
          collision.tiles.left = tile;
        }
      }
    }
  },

  checkPlatformCollisions(entityName, bounds, vel, platforms) {
    const collision = this.collisions[entityName];

    for (const platform of platforms) {
      if (!platform.active) continue;

      const platBounds = {
        left: platform.x,
        right: platform.x + (platform.width || this.tileSize * 2),
        top: platform.y,
        bottom: platform.y + (platform.height || this.tileSize / 2)
      };

      // Only collide from above
      if (vel.vy >= 0 && bounds.bottom >= platBounds.top && bounds.bottom <= platBounds.top + 10) {
        if (bounds.right > platBounds.left && bounds.left < platBounds.right) {
          collision.tiles.bottom = platform;
          collision.grounded = true;
        }
      }
    }
  },

  checkHazardDamage() {
    // Fireboy dies in water or goo
    for (const hazard of this.collisions.fireboy.hazards) {
      if (hazard.type === 'water' || hazard.type === 'goo') {
        this.collisions.fireboy.dead = true;
        this.collisions.fireboy.deathCause = hazard.type;
      }
    }

    // Watergirl dies in lava or goo
    for (const hazard of this.collisions.watergirl.hazards) {
      if (hazard.type === 'lava' || hazard.type === 'fire' || hazard.type === 'goo') {
        this.collisions.watergirl.dead = true;
        this.collisions.watergirl.deathCause = hazard.type;
      }
    }
  },

  boundsOverlap(a, b) {
    const aLeft = a.left !== undefined ? a.left : a.x;
    const aRight = a.right !== undefined ? a.right : a.x + (a.width || 32);
    const aTop = a.top !== undefined ? a.top : a.y;
    const aBottom = a.bottom !== undefined ? a.bottom : a.y + (a.height || 32);

    const bLeft = b.left !== undefined ? b.left : b.x;
    const bRight = b.right !== undefined ? b.right : b.x + (b.width || 32);
    const bTop = b.top !== undefined ? b.top : b.y;
    const bBottom = b.bottom !== undefined ? b.bottom : b.y + (b.height || 32);

    return aLeft < bRight && aRight > bLeft && aTop < bBottom && aBottom > bTop;
  },

  render(state, ctx) {
    const positions = state.read('entity_positions');
    if (!positions) return;

    ctx.save();

    // Draw Fireboy
    if (positions.fireboy) {
      this.drawEntity(ctx, positions.fireboy, 'fireboy');
    }

    // Draw Watergirl
    if (positions.watergirl) {
      this.drawEntity(ctx, positions.watergirl, 'watergirl');
    }

    // Draw debug collision info
    this.drawCollisionDebug(ctx);

    ctx.restore();
  },

  drawEntity(ctx, pos, type) {
    const halfW = this.entityWidth / 2;
    const collision = this.collisions[type];

    ctx.save();

    // Body color based on type
    const mainColor = type === 'fireboy' ? '#ff6a00' : '#00b4d8';
    const glowColor = type === 'fireboy' ? 'rgba(255,106,0,0.4)' : 'rgba(0,180,216,0.4)';
    const accentColor = type === 'fireboy' ? '#ffaa00' : '#90e0ef';

    // Draw glow effect
    const gradient = ctx.createRadialGradient(pos.x, pos.y - 22, 0, pos.x, pos.y - 22, 35);
    gradient.addColorStop(0, glowColor);
    gradient.addColorStop(1, 'transparent');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(pos.x, pos.y - 22, 35, 0, Math.PI * 2);
    ctx.fill();

    // Draw body
    ctx.fillStyle = mainColor;

    // Body shape (slightly rounded)
    ctx.beginPath();
    ctx.ellipse(pos.x, pos.y - 28, 12, 18, 0, 0, Math.PI * 2);
    ctx.fill();

    // Head
    ctx.beginPath();
    ctx.arc(pos.x, pos.y - 44, 10, 0, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.ellipse(pos.x - 4, pos.y - 45, 3, 4, 0, 0, Math.PI * 2);
    ctx.ellipse(pos.x + 4, pos.y - 45, 3, 4, 0, 0, Math.PI * 2);
    ctx.fill();

    // Pupils
    ctx.fillStyle = type === 'fireboy' ? '#330000' : '#001133';
    ctx.beginPath();
    ctx.arc(pos.x - 4, pos.y - 45, 1.5, 0, Math.PI * 2);
    ctx.arc(pos.x + 4, pos.y - 45, 1.5, 0, Math.PI * 2);
    ctx.fill();

    // Element effects
    if (type === 'fireboy') {
      // Flame hair
      ctx.fillStyle = accentColor;
      for (let i = 0; i < 3; i++) {
        const flameX = pos.x - 6 + i * 6;
        const flameH = 6 + Math.sin(Date.now() / 100 + i) * 3;
        ctx.beginPath();
        ctx.moveTo(flameX - 3, pos.y - 52);
        ctx.quadraticCurveTo(flameX, pos.y - 52 - flameH, flameX + 3, pos.y - 52);
        ctx.fill();
      }
    } else {
      // Ice crystals
      ctx.fillStyle = accentColor;
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1;
      for (let i = 0; i < 3; i++) {
        const crystalX = pos.x - 6 + i * 6;
        ctx.beginPath();
        ctx.moveTo(crystalX, pos.y - 52);
        ctx.lineTo(crystalX - 3, pos.y - 58);
        ctx.lineTo(crystalX + 3, pos.y - 58);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
      }
    }

    // Legs with walking animation
    const walkPhase = Math.sin(Date.now() / 150) * 0.3;
    ctx.fillStyle = mainColor;

    // Left leg
    ctx.beginPath();
    ctx.ellipse(pos.x - 5, pos.y - 8, 4, 8, walkPhase, 0, Math.PI * 2);
    ctx.fill();

    // Right leg
    ctx.beginPath();
    ctx.ellipse(pos.x + 5, pos.y - 8, 4, 8, -walkPhase, 0, Math.PI * 2);
    ctx.fill();

    // Grounded indicator
    if (collision && collision.grounded) {
      ctx.fillStyle = type === 'fireboy' ? 'rgba(255,170,0,0.3)' : 'rgba(144,224,239,0.3)';
      ctx.beginPath();
      ctx.ellipse(pos.x, pos.y, 14, 4, 0, 0, Math.PI * 2);
      ctx.fill();
    }

    // Death state
    if (collision && collision.dead) {
      ctx.fillStyle = 'rgba(255,0,0,0.5)';
      ctx.fillRect(pos.x - halfW, pos.y - this.entityHeight, this.entityWidth, this.entityHeight);

      ctx.fillStyle = '#ff0000';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('DEAD: ' + collision.deathCause, pos.x, pos.y - this.entityHeight - 5);
    }

    ctx.restore();
  },

  drawCollisionDebug(ctx) {
    ctx.fillStyle = 'rgba(255,255,255,0.9)';
    ctx.font = '11px monospace';

    let y = 20;

    // Fireboy status
    ctx.fillStyle = '#ff6a00';
    ctx.fillText('[Fireboy]', 10, y);
    y += 14;
    ctx.fillStyle = '#ffffff';
    const fb = this.collisions.fireboy;
    ctx.fillText(`Grounded: ${fb.grounded}`, 10, y); y += 12;
    ctx.fillText(`Hazards: ${fb.hazards.length}`, 10, y); y += 12;
    ctx.fillText(`Gems: ${fb.gems.length}`, 10, y); y += 12;
    ctx.fillText(`Exit: ${fb.exit ? 'Yes' : 'No'}`, 10, y); y += 12;

    // Watergirl status
    y = 20;
    ctx.fillStyle = '#00b4d8';
    ctx.fillText('[Watergirl]', 150, y);
    y += 14;
    ctx.fillStyle = '#ffffff';
    const wg = this.collisions.watergirl;
    ctx.fillText(`Grounded: ${wg.grounded}`, 150, y); y += 12;
    ctx.fillText(`Hazards: ${wg.hazards.length}`, 150, y); y += 12;
    ctx.fillText(`Gems: ${wg.gems.length}`, 150, y); y += 12;
    ctx.fillText(`Exit: ${wg.exit ? 'Yes' : 'No'}`, 150, y); y += 12;
  }
};

export default collision_detector;

const collision_detector = {
  name: 'collision_detector',

  collisions: null,
  tileSize: 32,
  entityWidth: 24,
  entityHeight: 40,

  init(state) {
    this.collisions = {
      fireboy: this.createEmptyCollisionData(),
      watergirl: this.createEmptyCollisionData()
    };
  },

  createEmptyCollisionData() {
    return {
      tiles: { top: [], bottom: [], left: [], right: [] },
      hazards: [],
      mechanisms: [],
      gems: [],
      exit: null,
      grounded: false,
      dead: false,
      deathCause: null
    };
  },

  resetCollisions(entityName) {
    this.collisions[entityName] = this.createEmptyCollisionData();
  },

  update(state, dt) {
    const positions = state.read('entity_positions');
    const velocities = state.read('velocity_vectors');
    const tileLayout = state.read('tile_layout');
    const hazardZones = state.read('hazard_zones');
    const mechanismState = state.read('mechanism_state');
    const gemCollection = state.read('gem_collection');

    if (!positions) return;

    this.resetCollisions('fireboy');
    this.resetCollisions('watergirl');

    if (positions.fireboy) {
      this.detectEntityCollisions(
        'fireboy',
        positions.fireboy,
        velocities && velocities.fireboy ? velocities.fireboy : { vx: 0, vy: 0 },
        tileLayout,
        hazardZones,
        mechanismState,
        gemCollection
      );
    }

    if (positions.watergirl) {
      this.detectEntityCollisions(
        'watergirl',
        positions.watergirl,
        velocities && velocities.watergirl ? velocities.watergirl : { vx: 0, vy: 0 },
        tileLayout,
        hazardZones,
        mechanismState,
        gemCollection
      );
    }
  },

  detectEntityCollisions(entityName, pos, vel, tileLayout, hazardZones, mechanismState, gemCollection) {
    const collision = this.collisions[entityName];
    const halfW = this.entityWidth / 2;
    const halfH = this.entityHeight / 2;

    const bounds = {
      left: pos.x - halfW,
      right: pos.x + halfW,
      top: pos.y - halfH,
      bottom: pos.y + halfH
    };

    if (tileLayout) {
      this.detectTileCollisions(collision, bounds, vel, tileLayout);
      this.detectExitCollision(collision, bounds, tileLayout);
    }

    if (hazardZones) {
      this.detectHazardCollisions(entityName, collision, bounds, hazardZones);
    }

    if (mechanismState) {
      this.detectMechanismCollisions(entityName, collision, pos, bounds, mechanismState);
    }

    if (gemCollection) {
      this.detectGemCollisions(entityName, collision, pos, gemCollection);
    }
  },

  detectTileCollisions(collision, bounds, vel, tileLayout) {
    const tiles = tileLayout.tiles || [];
    const ts = this.tileSize;

    const minTX = Math.floor(bounds.left / ts);
    const maxTX = Math.floor(bounds.right / ts);
    const minTY = Math.floor(bounds.top / ts);
    const maxTY = Math.floor(bounds.bottom / ts);

    collision.grounded = false;

    for (let ty = minTY; ty <= maxTY; ty++) {
      for (let tx = minTX; tx <= maxTX; tx++) {
        const row = tiles[ty];
        if (!row) continue;
        const tile = row[tx];
        if (!tile || !tile.solid) continue;

        const tileBounds = {
          left: tx * ts,
          right: (tx + 1) * ts,
          top: ty * ts,
          bottom: (ty + 1) * ts
        };

        if (!this.rectsOverlap(bounds, tileBounds)) continue;

        const overlapX = Math.min(bounds.right - tileBounds.left, tileBounds.right - bounds.left);
        const overlapY = Math.min(bounds.bottom - tileBounds.top, tileBounds.top - bounds.bottom);

        if (overlapX < overlapY) {
          if (bounds.left < tileBounds.left) {
            collision.tiles.right.push({ tile, tx, ty, overlap: overlapX });
          } else {
            collision.tiles.left.push({ tile, tx, ty, overlap: overlapX });
          }
        } else {
          if (bounds.top < tileBounds.top) {
            collision.tiles.bottom.push({ tile, tx, ty, overlap: overlapY });
            collision.grounded = true;
          } else {
            collision.tiles.top.push({ tile, tx, ty, overlap: overlapY });
          }
        }
      }
    }
  },

  detectHazardCollisions(entityName, collision, bounds, hazardZones) {
    const hazards = hazardZones.hazards || hazardZones || [];

    for (const hazard of hazards) {
      const hazardBounds = {
        left: hazard.x,
        right: hazard.x + (hazard.width || 32),
        top: hazard.y,
        bottom: hazard.y + (hazard.height || 32)
      };

      if (this.rectsOverlap(bounds, hazardBounds)) {
        collision.hazards.push(hazard);

        if (hazard.type === 'lava' && entityName === 'watergirl') {
          collision.dead = true;
          collision.deathCause = 'lava';
        } else if (hazard.type === 'water_pool' && entityName === 'fireboy') {
          collision.dead = true;
          collision.deathCause = 'water';
        } else if (hazard.type === 'green_goo' || hazard.type === 'acid') {
          collision.dead = true;
          collision.deathCause = hazard.type;
        }
      }
    }
  },

  detectMechanismCollisions(entityName, collision, pos, bounds, mechanismState) {
    const mechanisms = mechanismState.mechanisms || mechanismState || [];

    for (const mech of mechanisms) {
      const mechBounds = {
        left: mech.x,
        right: mech.x + (mech.width || 32),
        top: mech.y,
        bottom: mech.y + (mech.height || 32)
      };

      if (mech.type === 'door' && mech.open) continue;

      if (this.rectsOverlap(bounds, mechBounds)) {
        collision.mechanisms.push(mech);
      }

      if (mech.type === 'platform' && bounds.bottom <= mechBounds.top + 8 && bounds.bottom >= mechBounds.top - 4) {
        const horizOverlap = Math.min(bounds.right, mechBounds.right) - Math.max(bounds.left, mechBounds.left);
        if (horizOverlap > 0) {
          collision.tiles.bottom.push({ tile: { solid: true, platform: mech }, tx: 0, ty: 0, overlap: 0, platform: mech });
          collision.grounded = true;
        }
      }
    }
  },

  detectGemCollisions(entityName, collision, pos, gemCollection) {
    const gems = gemCollection.gems || [];
    const collected = gemCollection.collected || [];

    const halfW = this.entityWidth / 2;
    const halfH = this.entityHeight / 2;

    for (let i = 0; i < gems.length; i++) {
      if (collected.includes(i)) continue;

      const gem = gems[i];
      const gemRadius = gem.radius || 14;

      const closestX = Math.max(pos.x - halfW, Math.min(gem.x, pos.x + halfW));
      const closestY = Math.max(pos.y - halfH, Math.min(gem.y, pos.y + halfH));

      const dx = gem.x - closestX;
      const dy = gem.y - closestY;
      const distSq = dx * dx + dy * dy;

      if (distSq < gemRadius * gemRadius) {
        const isFireGem = gem.type === 'fire' || gem.type === 'orange' || gem.color === 'orange';
        const isWaterGem = gem.type === 'water' || gem.type === 'blue' || gem.color === 'blue';

        if ((isFireGem && entityName === 'fireboy') || (isWaterGem && entityName === 'watergirl')) {
          collision.gems.push({ gem, index: i });
        }
      }
    }
  },

  detectExitCollision(collision, bounds, tileLayout) {
    const exits = tileLayout.exits || (tileLayout.exit ? [tileLayout.exit] : []);

    for (const exit of exits) {
      const exitBounds = {
        left: exit.x,
        right: exit.x + (exit.width || 40),
        top: exit.y,
        bottom: exit.y + (exit.height || 60)
      };

      if (this.rectsOverlap(bounds, exitBounds)) {
        const centerDistX = Math.abs((bounds.left + bounds.right) / 2 - (exitBounds.left + exitBounds.right) / 2);
        const centerDistY = Math.abs((bounds.top + bounds.bottom) / 2 - (exitBounds.top + exitBounds.bottom) / 2);

        collision.exit = {
          exit,
          distance: Math.sqrt(centerDistX * centerDistX + centerDistY * centerDistY)
        };
      }
    }
  },

  rectsOverlap(a, b) {
    return a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top;
  },

  render(state, ctx) {
    // Debug visualization
  },

  getCollisions() {
    return this.collisions;
  },

  isGrounded(entityName) {
    return this.collisions[entityName] ? this.collisions[entityName].grounded : false;
  },

  isDead(entityName) {
    return this.collisions[entityName] ? this.collisions[entityName].dead : false;
  }
};

