const game_flow = {
  name: 'game_flow',

  init(state) {
    state.write('game_state', {
      status: 'playing',
      currentLevel: 1,
      totalLevels: 5,
      message: 'Level 1',
      messageTimer: 2,
      restartTimer: 0,
      nextLevelTimer: 0,
      deaths: 0,
      paused: false
    });

    state.write('level_config', {
      level: 1,
      width: 800,
      height: 600,
      gemCount: 10
    });

    this.keys = {};
    this.animTime = 0;
    this.setupInput();
  },

  setupInput() {
    if (typeof window !== 'undefined') {
      window.addEventListener('keydown', (e) => {
        this.keys[e.code] = true;
      });
      window.addEventListener('keyup', (e) => {
        this.keys[e.code] = false;
      });
    }
  },

  update(state, dt) {
    this.animTime += dt;
    const gameState = state.read('game_state');

    if (!gameState) return;

    // Handle restart key
    if (this.keys['KeyR'] && (gameState.status === 'playing' || gameState.status === 'lost')) {
      this.restartLevel(state, gameState);
      this.keys['KeyR'] = false;
      return;
    }

    // Handle pause
    if ((this.keys['Escape'] || this.keys['KeyP']) && 
        (gameState.status === 'playing' || gameState.paused)) {
      gameState.paused = !gameState.paused;
      gameState.message = gameState.paused ? 'PAUSED' : '';
      state.write('game_state', gameState);
      this.keys['Escape'] = false;
      this.keys['KeyP'] = false;
      return;
    }

    if (gameState.paused) return;

    // Handle won state
    if (gameState.status === 'won') {
      gameState.nextLevelTimer -= dt;
      if (gameState.nextLevelTimer <= 0) {
        this.advanceToNextLevel(state, gameState);
      } else if (this.keys['Space']) {
        this.advanceToNextLevel(state, gameState);
        this.keys['Space'] = false;
      }
      state.write('game_state', gameState);
      return;
    }

    // Handle lost state
    if (gameState.status === 'lost') {
      gameState.restartTimer -= dt;
      if (gameState.restartTimer <= 0) {
        this.restartLevel(state, gameState);
      }
      state.write('game_state', gameState);
      return;
    }

    // Handle complete state
    if (gameState.status === 'complete') {
      if (this.keys['Space'] || this.keys['Enter']) {
        this.resetGame(state, gameState);
        this.keys['Space'] = false;
        this.keys['Enter'] = false;
      }
      return;
    }

    // Check lose conditions
    if (this.checkLoseConditions(state)) {
      gameState.status = 'lost';
      gameState.message = 'LEVEL FAILED';
      gameState.restartTimer = 2.5;
      gameState.deaths++;
      state.write('game_state', gameState);
      return;
    }

    // Check win conditions
    if (this.checkWinConditions(state)) {
      gameState.status = 'won';
      gameState.message = gameState.currentLevel < gameState.totalLevels 
        ? 'LEVEL COMPLETE!' 
        : 'VICTORY!';
      gameState.nextLevelTimer = 2;
      state.write('game_state', gameState);
      return;
    }

    // Update message timer
    if (gameState.messageTimer > 0) {
      gameState.messageTimer -= dt;
      if (gameState.messageTimer <= 0) {
        gameState.message = '';
      }
    }

    state.write('game_state', gameState);
  },

  checkLoseConditions(state) {
    const playerState = state.read('player_state');
    const entityPositions = state.read('entity_positions');

    if (playerState) {
      if (playerState.fireboy && playerState.fireboy.dead) return true;
      if (playerState.watergirl && playerState.watergirl.dead) return true;
    }

    if (entityPositions) {
      const fb = entityPositions.fireboy;
      const wg = entityPositions.watergirl;

      if (fb && (fb.inWater || fb.inGoo || fb.inAcid)) return true;
      if (wg && (wg.inFire || wg.inGoo || wg.inAcid)) return true;
    }

    return false;
  },

  checkWinConditions(state) {
    const entityPositions = state.read('entity_positions');
    const gemCollection = state.read('gem_collection');

    if (!entityPositions) return false;

    const fireboyReady = entityPositions.fireboy && 
      (entityPositions.fireboy.atExit || entityPositions.fireboy.atFireExit);
    const watergirlReady = entityPositions.watergirl && 
      (entityPositions.watergirl.atExit || entityPositions.watergirl.atWaterExit);

    if (!fireboyReady || !watergirlReady) return false;

    if (gemCollection && gemCollection.total > 0) {
      const collected = gemCollection.collected || 0;
      if (collected < gemCollection.total) return false;
    }

    return true;
  },

  advanceToNextLevel(state, gameState) {
    if (gameState.currentLevel < gameState.totalLevels) {
      gameState.currentLevel++;
      gameState.status = 'playing';
      gameState.message = 'Level ' + gameState.currentLevel;
      gameState.messageTimer = 1.5;
      gameState.nextLevelTimer = 0;

      state.write('level_config', {
        level: gameState.currentLevel,
        width: 800,
        height: 600,
        gemCount: 8 + gameState.currentLevel * 3
      });
    } else {
      gameState.status = 'complete';
      gameState.message = 'ALL LEVELS COMPLETE!';
      gameState.messageTimer = 0;
    }
    state.write('game_state', gameState);
  },

  restartLevel(state, gameState) {
    gameState.status = 'playing';
    gameState.message = 'Level ' + gameState.currentLevel;
    gameState.messageTimer = 1;
    gameState.restartTimer = 0;
    gameState.paused = false;

    state.write('level_config', {
      level: gameState.currentLevel,
      width: 800,
      height: 600,
      gemCount: 8 + gameState.currentLevel * 3,
      restart: Date.now()
    });

    state.write('game_state', gameState);
  },

  resetGame(state, gameState) {
    gameState.currentLevel = 1;
    gameState.status = 'playing';
    gameState.message = 'Level 1';
    gameState.messageTimer = 2;
    gameState.deaths = 0;
    gameState.paused = false;

    state.write('level_config', {
      level: 1,
      width: 800,
      height: 600,
      gemCount: 10,
      restart: Date.now()
    });

    state.write('game_state', gameState);
  },

  render(state, ctx) {
    const gameState = state.read('game_state');
    if (!gameState) return;

    const canvas = ctx.canvas;
    const w = canvas.width;
    const h = canvas.height;

    this.renderHUD(state, ctx, w, h);

    if (gameState.paused) {
      this.renderPauseOverlay(ctx, w, h);
      return;
    }

    if (gameState.message && gameState.status !== 'playing') {
      this.renderStatusOverlay(ctx, w, h, gameState);
    } else if (gameState.message && gameState.messageTimer > 0) {
      this.renderLevelMessage(ctx, w, h, gameState);
    }
  },

