    ctx.font = 'bold 18px Arial';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText('Level ' + gameState.currentLevel + '/' + gameState.totalLevels, 15, 22);

    // Gem counter
    if (gemCollection) {
      const collected = gemCollection.collected || 0;
      const total = gemCollection.total || 0;
      const allCollected = total > 0 && collected >= total;

      ctx.fillStyle = allCollected ? '#00ff00' : '#ffff00';
      ctx.font = 'bold 16px Arial';
      ctx.textAlign = 'center';

      // Diamond shape
      ctx.beginPath();
      ctx.moveTo(w/2 - 30, 22);
      ctx.lineTo(w/2 - 22, 12);
      ctx.lineTo(w/2 - 14, 22);
      ctx.lineTo(w/2 - 22, 32);
      ctx.closePath();
      ctx.fill();

