const game_flow = {
  name: 'game_flow',

  init(state) {
    state.write('game_state', {
      status: 'playing',
      currentLevel: 1,
      totalLevels: 5,
      message: 'Level 1',
      messageTimer: 2,
      restartTimer: 0,
      nextLevelTimer: 0,
      deaths: 0,
      paused: false
    });

    state.write('level_config', {
      level: 1,
      width: 800,
      height: 600,
      gemCount: 10,
      restartCount: 0
    });

    this.keys = {};
    this.animTime = 0;
    this.setupInput();
  },

  setupInput() {
    if (typeof window !== 'undefined') {
      window.addEventListener('keydown', (e) => {
        this.keys[e.code] = true;
      });
      window.addEventListener('keyup', (e) => {
        this.keys[e.code] = false;
      });
    }
  },

  update(state, dt) {
    this.animTime += dt;
    const gameState = state.read('game_state');

    if (!gameState) return;

    // Handle restart key
    if (this.keys['KeyR'] && (gameState.status === 'playing' || gameState.status === 'lost')) {
      this.restartLevel(state, gameState);
      this.keys['KeyR'] = false;
      return;
    }

    // Handle pause toggle
    if ((this.keys['Escape'] || this.keys['KeyP']) && gameState.status === 'playing') {
      gameState.paused = !gameState.paused;
      gameState.message = gameState.paused ? 'PAUSED' : '';
      state.write('game_state', gameState);
      this.keys['Escape'] = false;
      this.keys['KeyP'] = false;
      return;
    }

    if (gameState.paused) return;

    // Handle level complete transition
    if (gameState.status === 'level_complete') {
      gameState.nextLevelTimer -= dt;
      if (gameState.nextLevelTimer <= 0) {
        this.advanceToNextLevel(state, gameState);
      }
      state.write('game_state', gameState);
      return;
    }

    // Handle game over state
    if (gameState.status === 'lost' || gameState.status === 'won') {
      return;
    }

    // Check win condition
    this.checkWinCondition(state, gameState);

    // Check lose condition
    if (gameState.status === 'playing') {
      this.checkLoseCondition(state, gameState);
    }

    // Update message timer
    if (gameState.messageTimer > 0) {
      gameState.messageTimer -= dt;
      if (gameState.messageTimer <= 0) {
        gameState.message = '';
      }
    }

    state.write('game_state', gameState);
  },

  checkWinCondition(state, gameState) {
    const gemCollection = state.read('gem_collection');
    const entityPositions = state.read('entity_positions');

    const gemsCollected = gemCollection ? (gemCollection.fireboyGems || 0) + (gemCollection.watergirlGems || 0) : 0;
    const totalGems = gemCollection ? gemCollection.totalGems || 0 : 0;
    const allGemsCollected = totalGems === 0 || gemsCollected >= totalGems;

    if (!entityPositions || !entityPositions.entities) return;

    const fireboy = entityPositions.entities.fireboy;
    const watergirl = entityPositions.entities.watergirl;

    if (!fireboy || !watergirl) return;

    const exitX = entityPositions.exitX || 750;
    const exitY = entityPositions.exitY || 550;
    const exitRadius = 40;

    const fireboyAtExit = this.isNearExit(fireboy, exitX, exitY, exitRadius);
    const watergirlAtExit = this.isNearExit(watergirl, exitX, exitY, exitRadius);

    if (fireboyAtExit && watergirlAtExit && allGemsCollected) {
      gameState.status = 'level_complete';
      gameState.message = 'Level Complete!';
      gameState.nextLevelTimer = 2;
      state.write('game_state', gameState);
    }
  },

  isNearExit(entity, exitX, exitY, radius) {
    if (!entity) return false;
    const dx = (entity.x || 0) - exitX;
    const dy = (entity.y || 0) - exitY;
    return Math.sqrt(dx * dx + dy * dy) < radius;
  },

  checkLoseCondition(state, gameState) {
    const playerState = state.read('player_state');

    if (!playerState) return;

    const fireboyDead = playerState.fireboyDead || false;
    const watergirlDead = playerState.watergirlDead || false;

    if (fireboyDead || watergirlDead) {
      gameState.deaths = (gameState.deaths || 0) + 1;
      gameState.status = 'lost';
      gameState.message = fireboyDead ? 'Fireboy Died! Press R' : 'Watergirl Died! Press R';
      state.write('game_state', gameState);
    }
  },

  restartLevel(state, gameState) {
    gameState.status = 'playing';
    gameState.message = 'Level ' + gameState.currentLevel;
    gameState.messageTimer = 2;
    gameState.restartTimer = 0;
    gameState.paused = false;
    state.write('game_state', gameState);

    const levelConfig = state.read('level_config') || {};
    levelConfig.restartCount = (levelConfig.restartCount || 0) + 1;
    state.write('level_config', levelConfig);
  },

  advanceToNextLevel(state, gameState) {
    const nextLevel = gameState.currentLevel + 1;

    if (nextLevel > gameState.totalLevels) {
      gameState.status = 'won';
      gameState.message = 'Victory! Deaths: ' + gameState.deaths;
      gameState.messageTimer = 5;
      state.write('game_state', gameState);
      return;
    }

    gameState.currentLevel = nextLevel;
    gameState.status = 'playing';
    gameState.message = 'Level ' + nextLevel;
    gameState.messageTimer = 2;
    gameState.nextLevelTimer = 0;
    state.write('game_state', gameState);

    const levelConfig = state.read('level_config') || {};
    levelConfig.level = nextLevel;
    levelConfig.width = 800;
    levelConfig.height = 600;
    levelConfig.gemCount = 10 + (nextLevel - 1) * 2;
    levelConfig.restartCount = 0;
    state.write('level_config', levelConfig);
  },

  render(state, ctx) {
    const gameState = state.read('game_state');
    const gemCollection = state.read('gem_collection');

    if (!gameState) return;

    const canvas = ctx.canvas;

    // Draw UI panel
    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(0, 0, canvas.width, 50);

    // Level info
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 18px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('Level ' + gameState.currentLevel + '/' + gameState.totalLevels, 20, 32);

    // Gem counter with icons
    if (gemCollection) {
      const fireGems = gemCollection.fireboyGems || 0;
      const waterGems = gemCollection.watergirlGems || 0;
      const totalGems = gemCollection.totalGems || 0;

      ctx.textAlign = 'center';
      ctx.fillStyle = '#ff8844';
      ctx.fillText('\u25C6 ' + fireGems, canvas.width / 2 - 50, 32);
      ctx.fillStyle = '#44aaff';
      ctx.fillText('\u25C7 ' + waterGems, canvas.width / 2 + 50, 32);
      ctx.fillStyle = '#aaaaaa';
      ctx.font = '14px Arial';
      ctx.fillText('(' + (fireGems + waterGems) + '/' + totalGems + ')', canvas.width / 2, 20);
    }

    // Deaths counter
    ctx.fillStyle = '#ff6666';
    ctx.font = 'bold 16px Arial';
    ctx.textAlign = 'right';
    ctx.fillText('Deaths: ' + (gameState.deaths || 0), canvas.width - 20, 32);

    // Draw message overlay
    if (gameState.message && gameState.message.length > 0) {
      const boxWidth = 320;
      const boxHeight = 80;
      const boxX = canvas.width / 2 - boxWidth / 2;
      const boxY = canvas.height / 2 - boxHeight / 2;

      ctx.fillStyle = 'rgba(0, 0, 0, 0.85)';
      ctx.strokeStyle = gameState.status === 'lost' ? '#ff4444' : 
                        gameState.status === 'won' ? '#44ff44' : '#ffffff';
      ctx.lineWidth = 3;
      ctx.fillRect(boxX, boxY, boxWidth, boxHeight);
      ctx.strokeRect(boxX, boxY, boxWidth, boxHeight);

      ctx.fillStyle = gameState.status === 'lost' ? '#ff6666' : 
                      gameState.status === 'won' ? '#66ff66' : '#ffffff';
      ctx.font = 'bold 24px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(gameState.message, canvas.width / 2, canvas.height / 2);

      if (gameState.status === 'playing') {
        ctx.font = '12px Arial';
        ctx.fillStyle = '#aaaaaa';
        ctx.fillText('R - Restart | P - Pause', canvas.width / 2, canvas.height / 2 + 25);
      }
    }

    // Draw pause overlay
    if (gameState.paused) {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
      ctx.fillRect(0, 50, canvas.width, canvas.height - 50);

      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 48px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('PAUSED', canvas.width / 2, canvas.height / 2);

      ctx.font = '18px Arial';
      ctx.fillStyle = '#aaaaaa';
      ctx.fillText('Press P or ESC to resume', canvas.width / 2, canvas.height / 2 + 40);
    }
  }
};

