const gravity_system = {
  name: 'gravity_system',

  init(state) {
    state.write('velocity_vectors', {
      fireboy: { vx: 0, vy: 0 },
      watergirl: { vx: 0, vy: 0 }
    });
  },

  update(state, dt) {
    const levelConfig = state.read('level_config') || {};
    const gravity = levelConfig.gravity || 800;
    const maxFallSpeed = levelConfig.maxFallSpeed || 600;

    const mechanismState = state.read('mechanism_state') || {};

    let velocities = state.read('velocity_vectors');
    if (!velocities) {
      velocities = {
        fireboy: { vx: 0, vy: 0 },
        watergirl: { vx: 0, vy: 0 }
      };
    }

    const fireboyVel = velocities.fireboy || { vx: 0, vy: 0 };
    const watergirlVel = velocities.watergirl || { vx: 0, vy: 0 };

    const fireboyState = mechanismState.fireboy || {};
    const watergirlState = mechanismState.watergirl || {};

    let fireboyVy = fireboyVel.vy;
    let watergirlVy = watergirlVel.vy;

    if (!fireboyState.onGround) {
      fireboyVy = fireboyVy + gravity * dt;
      fireboyVy = Math.min(fireboyVy, maxFallSpeed);
    }

    if (!watergirlState.onGround) {
      watergirlVy = watergirlVy + gravity * dt;
      watergirlVy = Math.min(watergirlVy, maxFallSpeed);
    }

    state.write('velocity_vectors', {
      fireboy: {
        vx: fireboyVel.vx,
        vy: fireboyVy
      },
      watergirl: {
        vx: watergirlVel.vx,
        vy: watergirlVy
      }
    });
  },

  render(state, ctx) {
    // Gravity is invisible - no visual rendering needed
  }
};

