const impulse_handler = {
  name: 'impulse_handler',

  init(state) {
    state.write('velocity_vectors', {
      fireboy: { x: 0, y: 0 },
      watergirl: { x: 0, y: 0 },
      _impulse: {
        jumpHeld: { fireboy: false, watergirl: false },
        consumedBoosts: []
      }
    });
  },

  update(state, dt) {
    const keys = state.read('input_keys') || {};
    const mech = state.read('mechanism_state') || {};
    const config = state.read('level_config') || {};
    const vel = state.read('velocity_vectors');

    const jumpForce = config.jumpForce || 450;
    const boostForce = config.boostForce || 580;

    const grounded = mech.grounded || { fireboy: false, watergirl: false };
    const boosts = mech.boosts || [];

    const fbVel = (vel && vel.fireboy) || { x: 0, y: 0 };
    const wgVel = (vel && vel.watergirl) || { x: 0, y: 0 };
    const impulse = (vel && vel._impulse) || { 
      jumpHeld: { fireboy: false, watergirl: false },
      consumedBoosts: []
    };

    const prevJumpHeld = impulse.jumpHeld || { fireboy: false, watergirl: false };
    const consumedBoosts = impulse.consumedBoosts || [];

    const fbJumpTrigger = keys.fireboyJump && !prevJumpHeld.fireboy;
    const wgJumpTrigger = keys.watergirlJump && !prevJumpHeld.watergirl;

    let newFbVel = { x: fbVel.x, y: fbVel.y };
    let newWgVel = { x: wgVel.x, y: wgVel.y };
    let newConsumedBoosts = [];

    if (fbJumpTrigger && grounded.fireboy) {
      newFbVel.y = -jumpForce;
    }

    if (wgJumpTrigger && grounded.watergirl) {
      newWgVel.y = -jumpForce;
    }

    boosts.forEach(function(boost) {
      if (!boost.id || consumedBoosts.indexOf(boost.id) !== -1) return;

      const isFireboy = boost.target === 'fireboy';
      const isWatergirl = boost.target === 'watergirl';

      if (isFireboy) {
        if (boost.type === 'spring' || boost.type === 'jumppad') {
          newFbVel.y = -boostForce;
          newConsumedBoosts.push(boost.id);
        } else if (boost.type === 'lateral_boost' && boost.direction) {
          newFbVel.x += boost.direction * boostForce * 0.8;
          newConsumedBoosts.push(boost.id);
        } else if (boost.type === 'burst' && boost.vx !== undefined && boost.vy !== undefined) {
          newFbVel.x += boost.vx;
          newFbVel.y += boost.vy;
          newConsumedBoosts.push(boost.id);
        }
      }

      if (isWatergirl) {
        if (boost.type === 'spring' || boost.type === 'jumppad') {
          newWgVel.y = -boostForce;
          newConsumedBoosts.push(boost.id);
        } else if (boost.type === 'lateral_boost' && boost.direction) {
          newWgVel.x += boost.direction * boostForce * 0.8;
          newConsumedBoosts.push(boost.id);
        } else if (boost.type === 'burst' && boost.vx !== undefined && boost.vy !== undefined) {
          newWgVel.x += boost.vx;
          newWgVel.y += boost.vy;
          newConsumedBoosts.push(boost.id);
        }
      }
    });

    state.write('velocity_vectors', {
      fireboy: newFbVel,
      watergirl: newWgVel,
      _impulse: {
        jumpHeld: {
          fireboy: !!keys.fireboyJump,
          watergirl: !!keys.watergirlJump
        },
        consumedBoosts: newConsumedBoosts
      }
    });
  },

  render(state, ctx) {}
};

