    state.write('entity_positions', {
      fireboy: {
        x: spawnPoints.fireboy.x,
        y: spawnPoints.fireboy.y,
        width: 32,
        height: 48,
        facingRight: true,
        animFrame: 0,
        walking: false,
        grounded: false
      },
      watergirl: {
        x: spawnPoints.watergirl.x,
        y: spawnPoints.watergirl.y,
        width: 32,
        height: 48,
        facingRight: true,
        animFrame: 0,
        walking: false,
        grounded: false
      }
    });

    state.write('mechanism_state', {
      movingPlatforms: [],
      activeMechanisms: {},
      lastIntegrationTime: 0,
      totalDisplacement: { fireboy: { x: 0, y: 0 }, watergirl: { x: 0, y: 0 } }
    });
  },

  update(state, dt) {
    const velocities = state.read('velocity_vectors') || {};
    const positions = state.read('entity_positions') || {};
    const levelConfig = state.read('level_config') || {};
    const inputKeys = state.read('input_keys') || {};
    const mechanismState = state.read('mechanism_state') || {};

    if (!positions.fireboy || !positions.watergirl) return;

    const newPositions = {
      fireboy: { ...positions.fireboy },
      watergirl: { ...positions.watergirl }
    };

    const bounds = levelConfig.bounds || { minX: 0, maxX: 800, minY: 0, maxY: 600 };
    const maxSpeed = levelConfig.maxSpeed || 400;

    // Integrate Fireboy
    if (velocities.fireboy) {
      const vx = Math.max(-maxSpeed, Math.min(maxSpeed, velocities.fireboy.x || 0));
      const vy = Math.max(-maxSpeed * 2, Math.min(maxSpeed * 2, velocities.fireboy.y || 0));

      const prevX = newPositions.fireboy.x;
      newPositions.fireboy.x += vx * dt;
      newPositions.fireboy.y += vy * dt;

      newPositions.fireboy.walking = Math.abs(vx) > 10;
      if (vx !== 0) {
        newPositions.fireboy.facingRight = vx > 0;
      }
    }

    // Integrate Watergirl
    if (velocities.watergirl) {
      const vx = Math.max(-maxSpeed, Math.min(maxSpeed, velocities.watergirl.x || 0));
      const vy = Math.max(-maxSpeed * 2, Math.min(maxSpeed * 2, velocities.watergirl.y || 0));

      const prevX = newPositions.watergirl.x;
      newPositions.watergirl.x += vx * dt;
      newPositions.watergirl.y += vy * dt;

      newPositions.watergirl.walking = Math.abs(vx) > 10;
      if (vx !== 0) {
        newPositions.watergirl.facingRight = vx > 0;
      }
    }

    // Clamp to bounds
    newPositions.fireboy.x = Math.max(bounds.minX, Math.min(bounds.maxX - 32, newPositions.fireboy.x));
    newPositions.fireboy.y = Math.max(bounds.minY, Math.min(bounds.maxY - 48, newPositions.fireboy.y));

    newPositions.watergirl.x = Math.max(bounds.minX, Math.min(bounds.maxX - 32, newPositions.watergirl.x));
    newPositions.watergirl.y = Math.max(bounds.minY, Math.min(bounds.maxY - 48, newPositions.watergirl.y));

    // Update animation frames
    const animSpeed = 10;
    newPositions.fireboy.animFrame = (newPositions.fireboy.animFrame + (newPositions.fireboy.walking ? animSpeed * dt : 0)) % 4;
    newPositions.watergirl.animFrame = (newPositions.watergirl.animFrame + (newPositions.watergirl.walking ? animSpeed * dt : 0)) % 4;

    state.write('entity_positions', newPositions);

    // Update mechanism state
    const newMechanismState = {
      ...mechanismState,
      lastIntegrationTime: Date.now(),
      dt: dt,
      totalDisplacement: {
        fireboy: {
          x: (velocities.fireboy?.x || 0) * dt,
          y: (velocities.fireboy?.y || 0) * dt
        },
        watergirl: {
          x: (velocities.watergirl?.x || 0) * dt,
          y: (velocities.watergirl?.y || 0) * dt
        }
      }
    };

    state.write('mechanism_state', newMechanismState);
  },

  render(state, ctx) {
    const positions = state.read('entity_positions');
    if (!positions) return;

    const time = Date.now();

    if (positions.fireboy) {
      this.drawFireboy(ctx, positions.fireboy, time);
    }

    if (positions.watergirl) {
      this.drawWatergirl(ctx, positions.watergirl, time);
    }
  },

  drawFireboy(ctx, entity, time) {
    const { x, y, facingRight, walking, animFrame } = entity;

    ctx.save();

    if (!facingRight) {
      ctx.translate(x + 16, y);
      ctx.scale(-1, 1);
    } else {
      ctx.translate(x, y);
    }

    // Flame aura
    const auraSize = 18 + Math.sin(time / 100) * 2;
    const gradient = ctx.createRadialGradient(16, 20, 0, 16, 20, auraSize);
    gradient.addColorStop(0, 'rgba(255, 150, 0, 0.4)');
    gradient.addColorStop(1, 'rgba(255, 100, 0, 0)');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(16, 20, auraSize, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = '#FF6B00';
    ctx.fillRect(8, 16, 16, 24);

    // Head
    ctx.beginPath();
    ctx.arc(16, 12, 10, 0, Math.PI * 2);
    ctx.fill();

    // Flame hair
    const flameWave = Math.sin(time / 80) * 3;
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.moveTo(6, 10);
    ctx.quadraticCurveTo(10, -5 + flameWave, 16, 2);
    ctx.quadraticCurveTo(22, -5 - flameWave, 26, 10);
    ctx.lineTo(22, 10);
    ctx.fill();

    // Inner flame
    ctx.fillStyle = '#FF4500';
    ctx.beginPath();
    ctx.moveTo(10, 8);
    ctx.quadraticCurveTo(13, 0 + flameWave, 16, 5);
    ctx.quadraticCurveTo(19, 0 - flameWave, 22, 8);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#FFF';
    ctx.fillRect(11, 10, 4, 4);
    ctx.fillRect(17, 10, 4, 4);
    ctx.fillStyle = '#000';
    ctx.fillRect(13, 11, 2, 2);
    ctx.fillRect(19, 11, 2, 2);

    // Legs with walking animation
    const legAnim = walking ? Math.sin(animFrame * Math.PI / 2) * 5 : 0;
    ctx.fillStyle = '#FF4500';
    ctx.fillRect(9, 40, 5, 8 + legAnim);
    ctx.fillRect(18, 40, 5, 8 - legAnim);

    ctx.restore();
  },

  drawWatergirl(ctx, entity, time) {
    const { x, y, facingRight, walking, animFrame } = entity;

    ctx.save();

    if (!facingRight) {
      ctx.translate(x + 16, y);
      ctx.scale(-1, 1);
    } else {
      ctx.translate(x, y);
    }

    // Frost aura
    const auraSize = 18 + Math.sin(time / 150) * 2;
    const gradient = ctx.createRadialGradient(16, 20, 0, 16, 20, auraSize);
    gradient.addColorStop(0, 'rgba(100, 200, 255, 0.4)');
    gradient.addColorStop(1, 'rgba(50, 150, 255, 0)');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(16, 20, auraSize, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = '#4FC3F7';
    ctx.fillRect(8, 16, 16, 24);

    // Head
    ctx.beginPath();
    ctx.arc(16, 12, 10, 0, Math.PI * 2);
    ctx.fill();

    // Ice crystal hair
    const crystalWave = Math.sin(time / 120) * 2;
    ctx.fillStyle = '#81D4FA';

    // Crystal points
    for (let i = 0; i < 5; i++) {
      const px = 5 + i * 5.5;
      const height = 6 + (i % 2) * 4 + Math.sin(time / 200 + i) * 2;
      ctx.beginPath();
      ctx.moveTo(px, 6);
      ctx.lineTo(px + 2.75, -height + crystalWave);
      ctx.lineTo(px + 5.5, 6);
      ctx.fill();
    }

    // Eyes
    ctx.fillStyle = '#FFF';
    ctx.fillRect(11, 10, 4, 4);
    ctx.fillRect(17, 10, 4, 4);
    ctx.fillStyle = '#1E88E5';
    ctx.fillRect(13, 11, 2, 2);
    ctx.fillRect(19, 11, 2, 2);

    // Frost sparkles
    ctx.fillStyle = '#E1F5FE';
    const sparkleTime = time / 300;
    for (let i = 0; i < 3; i++) {
      const sx = 8 + Math.sin(sparkleTime + i * 2) * 10;
      const sy = 18 + Math.cos(sparkleTime + i * 2) * 10;
      ctx.globalAlpha = 0.5 + Math.sin(time / 100 + i) * 0.3;
      ctx.beginPath();
      ctx.arc(sx, sy, 2, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Legs with walking animation
    const legAnim = walking ? Math.sin(animFrame * Math.PI / 2) * 5 : 0;
    ctx.fillStyle = '#29B6F6';
    ctx.fillRect(9, 40, 5, 8 + legAnim);
    ctx.fillRect(18, 40, 5, 8 - legAnim);

    ctx.restore();
  }
};

