const kinematic_integrator = {
  name: 'kinematic_integrator',

  init(state) {
    const levelConfig = state.read('level_config') || {};
    const spawnPoints = levelConfig.spawnPoints || {
      fireboy: { x: 100, y: 400 },
      watergirl: { x: 180, y: 400 }
    };

    state.write('entity_positions', {
      fireboy: {
        x: spawnPoints.fireboy.x,
        y: spawnPoints.fireboy.y,
        width: 32,
        height: 48,
        facingRight: true,
        animFrame: 0,
        walkTimer: 0,
        walking: false,
        grounded: false
      },
      watergirl: {
        x: spawnPoints.watergirl.x,
        y: spawnPoints.watergirl.y,
        width: 32,
        height: 48,
        facingRight: true,
        animFrame: 0,
        walkTimer: 0,
        walking: false,
        grounded: false
      }
    });

    state.write('mechanism_state', {
      movingPlatforms: [],
      activeMechanisms: {},
      lastIntegrationTime: 0,
      totalDisplacement: { fireboy: { x: 0, y: 0 }, watergirl: { x: 0, y: 0 } }
    });
  },

  update(state, dt) {
    const velocities = state.read('velocity_vectors') || {};
    const positions = state.read('entity_positions') || {};
    const levelConfig = state.read('level_config') || {};
    const mechanismState = state.read('mechanism_state') || {};

    if (!positions.fireboy || !positions.watergirl) return;

    const newPositions = {
      fireboy: { ...positions.fireboy },
      watergirl: { ...positions.watergirl }
    };

    const newMechanismState = { ...mechanismState };

    const bounds = levelConfig.bounds || { minX: 0, maxX: 800, minY: 0, maxY: 600 };
    const maxSpeed = levelConfig.maxSpeed || 400;

    ['fireboy', 'watergirl'].forEach(function(entity) {
      const vel = velocities[entity] || { x: 0, y: 0 };
      const pos = newPositions[entity];

      const clampedVel = {
        x: Math.max(-maxSpeed, Math.min(maxSpeed, vel.x)),
        y: Math.max(-maxSpeed * 1.5, Math.min(maxSpeed * 1.5, vel.y))
      };

      const dx = clampedVel.x * dt;
      const dy = clampedVel.y * dt;

      pos.x = Math.max(bounds.minX, Math.min(bounds.maxX - pos.width, pos.x + dx));
      pos.y = Math.max(bounds.minY, Math.min(bounds.maxY - pos.height, pos.y + dy));

      const isWalking = Math.abs(clampedVel.x) > 15;
      pos.walking = isWalking;

      if (isWalking) {
        pos.walkTimer = (pos.walkTimer || 0) + dt;
        pos.animFrame = Math.floor(pos.walkTimer * 10) % 4;
        pos.facingRight = clampedVel.x > 0;
      } else {
        pos.animFrame = 0;
        pos.walkTimer = 0;
      }

      pos.grounded = clampedVel.y >= -5 && clampedVel.y <= 5;

      if (!newMechanismState.totalDisplacement) {
        newMechanismState.totalDisplacement = { fireboy: { x: 0, y: 0 }, watergirl: { x: 0, y: 0 } };
      }
      if (!newMechanismState.totalDisplacement[entity]) {
        newMechanismState.totalDisplacement[entity] = { x: 0, y: 0 };
      }
      newMechanismState.totalDisplacement[entity] = {
        x: newMechanismState.totalDisplacement[entity].x + dx,
        y: newMechanismState.totalDisplacement[entity].y + dy
      };
    });

    newMechanismState.lastIntegrationTime = dt;

    state.write('entity_positions', newPositions);
    state.write('mechanism_state', newMechanismState);
  },

  render(state, ctx) {
    const positions = state.read('entity_positions') || {};

    ['fireboy', 'watergirl'].forEach(function(entity) {
      const pos = positions[entity];
      if (!pos) return;

      ctx.save();

      const drawX = pos.facingRight ? pos.x : pos.x + pos.width;
      const scaleX = pos.facingRight ? 1 : -1;

      ctx.translate(drawX, pos.y);
      ctx.scale(scaleX, 1);

      if (entity === 'fireboy') {
        // Fireboy body - orange
        ctx.fillStyle = '#FF6B35';
        ctx.fillRect(4, 10, 24, 32);

        // Flame head
        ctx.fillStyle = '#FFD93D';
        const flameWave = pos.walking ? Math.sin((pos.walkTimer || 0) * 25) * 3 : Math.sin(Date.now() * 0.005) * 2;
        ctx.beginPath();
        ctx.moveTo(6, 10);
        ctx.quadraticCurveTo(10, -2 + flameWave, 16, 0);
        ctx.quadraticCurveTo(22, -4 + flameWave, 26, 10);
        ctx.closePath();
        ctx.fill();

        // Inner flame
        ctx.fillStyle = '#FF8C42';
        ctx.beginPath();
        ctx.moveTo(10, 10);
        ctx.quadraticCurveTo(13, 2 + flameWave * 0.5, 16, 4);
        ctx.quadraticCurveTo(19, 0 + flameWave * 0.5, 22, 10);
        ctx.closePath();
        ctx.fill();

        // Eyes
        ctx.fillStyle = '#1A1A1A';
        ctx.fillRect(9, 18, 4, 5);
        ctx.fillRect(19, 18, 4, 5);

        // Eye glow
        ctx.fillStyle = '#FFF';
        ctx.fillRect(10, 19, 2, 2);
        ctx.fillRect(20, 19, 2, 2);

        // Legs with walk animation
        ctx.fillStyle = '#CC4E1D';
        const legAnim = pos.walking ? Math.sin(pos.animFrame * Math.PI * 0.5) * 6 : 0;
        ctx.fillRect(6, 42 - legAnim, 8, 6 + legAnim);
        ctx.fillRect(18, 42 + legAnim, 8, 6 - legAnim);

        // Feet glow
        ctx.fillStyle = '#FF8C42';
        ctx.fillRect(6, 46 - legAnim, 8, 2);
        ctx.fillRect(18, 46 + legAnim, 8, 2);

      } else {
        // Watergirl body - blue
        ctx.fillStyle = '#29B6F6';
        ctx.fillRect(4, 10, 24, 32);

        // Ice crystal hair
        ctx.fillStyle = '#B3E5FC';
        const crystalShimmer = pos.walking ? Math.sin((pos.walkTimer || 0) * 20) * 2 : Math.sin(Date.now() * 0.003) * 1;
        ctx.beginPath();
        ctx.moveTo(6, 10);
        ctx.lineTo(8, 0 + crystalShimmer);
        ctx.lineTo(12, 6);
        ctx.lineTo(16, -2 + crystalShimmer);
        ctx.lineTo(20, 6);
        ctx.lineTo(24, 0 + crystalShimmer);
        ctx.lineTo(26, 10);
        ctx.closePath();
        ctx.fill();

        // Hair shine
        ctx.fillStyle = '#E1F5FE';
        ctx.beginPath();
        ctx.moveTo(12, 4);
        ctx.lineTo(14, 0);
        ctx.lineTo(16, 4);
        ctx.closePath();
        ctx.fill();

        // Eyes
        ctx.fillStyle = '#01579B';
        ctx.fillRect(9, 18, 4, 5);
        ctx.fillRect(19, 18, 4, 5);

        // Eye shine
        ctx.fillStyle = '#B3E5FC';
        ctx.fillRect(10, 19, 2, 2);
        ctx.fillRect(20, 19, 2, 2);

        // Legs with walk animation
        ctx.fillStyle = '#0288D1';
        const legAnim = pos.walking ? Math.sin(pos.animFrame * Math.PI * 0.5) * 5 : 0;
        ctx.fillRect(6, 42 - legAnim, 8, 6 + legAnim);
        ctx.fillRect(18, 42 + legAnim, 8, 6 - legAnim);

        // Ice feet
        ctx.fillStyle = '#4FC3F7';
        ctx.fillRect(6, 46 - legAnim, 8, 2);
        ctx.fillRect(18, 46 + legAnim, 8, 2);
      }

      ctx.restore();
    });
  }
};

