const level_generator = {
  name: 'level_generator',

  init(state) {
    state.write('entity_positions', {
      fireboy: { 
        x: 100, y: 400, vx: 0, vy: 0, 
        onGround: false, facing: 1, 
        animFrame: 0, animTime: 0, walking: false
      },
      watergirl: { 
        x: 160, y: 400, vx: 0, vy: 0, 
        onGround: false, facing: 1, 
        animFrame: 0, animTime: 0, walking: false
      }
    });

    state.write('tile_layout', {
      tiles: [],
      width: 800,
      height: 480
    });

    state.write('hazard_zones', {
      lava: [],
      water: [],
      goo: []
    });

    state.write('mechanism_state', {
      levers: [],
      doors: [],
      buttons: [],
      platforms: []
    });

    state.write('gem_collection', {
      collected: [],
      total: 0,
      gems: []
    });

    state.write('player_state', {
      level: 1,
      score: 0,
      lives: 3,
      levelStartTime: Date.now()
    });
  },

  update(state, dt) {
    const game_state = state.read('game_state');
    const level_config = state.read('level_config');

    if (!game_state) return;

    if (game_state.status === 'loading' || game_state.needsLevelGeneration) {
      const levelNum = game_state.currentLevel || 1;
      this.generateLevel(state, level_config, levelNum);
    }
  },

  render(state, ctx) {
    // Visual preview of generated level structure (debug)
    const tile_layout = state.read('tile_layout');
    if (!tile_layout || !tile_layout.tiles) return;

    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, 800, 480);

    // Draw tiles
    tile_layout.tiles.forEach(tile => {
      if (tile.type === 'solid') {
        ctx.fillStyle = '#4a4a6a';
        ctx.fillRect(tile.x, tile.y, tile.w, tile.h);
        ctx.strokeStyle = '#6a6a8a';
        ctx.strokeRect(tile.x, tile.y, tile.w, tile.h);
      }
    });

    // Draw spawn points indicator
    if (tile_layout.spawnPoints) {
      ctx.fillStyle = 'rgba(255, 140, 0, 0.5)';
      ctx.beginPath();
      ctx.arc(tile_layout.spawnPoints.fireboy.x, tile_layout.spawnPoints.fireboy.y, 15, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = 'rgba(100, 180, 255, 0.5)';
      ctx.beginPath();
      ctx.arc(tile_layout.spawnPoints.watergirl.x, tile_layout.spawnPoints.watergirl.y, 15, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw exit
    if (tile_layout.exit) {
      ctx.fillStyle = '#00ff88';
      ctx.fillRect(tile_layout.exit.x, tile_layout.exit.y - 48, 32, 64);
    }
  },

  generateLevel(state, config, levelNum) {
    const difficulty = Math.min(levelNum, 10);
    const seed = levelNum * 12345;
    const rng = this.seededRandom(seed);

    const tileWidth = 32;
    const tileHeight = 32;
    const gridWidth = 25;
    const gridHeight = 15;

    // Generate tile layout
    const tiles = [];
    const grid = [];

    for (let y = 0; y < gridHeight; y++) {
      grid[y] = [];
      for (let x = 0; x < gridWidth; x++) {
        grid[y][x] = 0;
      }
    }

    // Floor
    for (let x = 0; x < gridWidth; x++) {
      grid[gridHeight - 1][x] = 1;
      tiles.push({ x: x * tileWidth, y: (gridHeight - 1) * tileHeight, w: tileWidth, h: tileHeight, type: 'solid' });
    }

    // Walls
    for (let y = 0; y < gridHeight; y++) {
      grid[y][0] = 1;
      grid[y][gridWidth - 1] = 1;
      tiles.push({ x: 0, y: y * tileHeight, w: tileWidth, h: tileHeight, type: 'solid' });
      tiles.push({ x: (gridWidth - 1) * tileWidth, y: y * tileHeight, w: tileWidth, h: tileHeight, type: 'solid' });
    }

    // Generate platforms with solvability in mind
    const numPlatforms = 4 + Math.floor(difficulty * 1.2);
    let lastPlatformY = gridHeight - 3;

    for (let i = 0; i < numPlatforms; i++) {
      const px = 2 + Math.floor(rng() * (gridWidth - 8));
      const py = Math.max(2, lastPlatformY - Math.floor(rng() * 3) - 1);
      const pwidth = 2 + Math.floor(rng() * 4);

      for (let w = 0; w < pwidth && (px + w) < gridWidth - 2; w++) {
        if (grid[py][px + w] === 0) {
          grid[py][px + w] = 1;
          tiles.push({ 
            x: (px + w) * tileWidth, 
            y: py * tileHeight, 
            w: tileWidth, 
            h: tileHeight, 
            type: 'solid' 
          });
        }
      }
      lastPlatformY = py;
    }

    // Create path to exit (ensure solvability)
    const exitX = gridWidth - 3;
    const exitY = gridHeight - 3;
    grid[exitY][exitX] = 0;
    grid[exitY - 1][exitX] = 0;

    const spawnPoints = {
      fireboy: { x: 80, y: (gridHeight - 3) * tileHeight },
      watergirl: { x: 130, y: (gridHeight - 3) * tileHeight }
    };

    const exit = { x: exitX * tileWidth, y: exitY * tileHeight };

    state.write('tile_layout', {
      tiles,
      grid,
      spawnPoints,
      exit,
      width: gridWidth * tileWidth,
      height: gridHeight * tileHeight
    });

    // Generate hazards
    const hazards = { lava: [], water: [], goo: [] };
    const numHazards = Math.floor(difficulty * 0.6);

    for (let i = 0; i < numHazards; i++) {
      const hx = 100 + rng() * (gridWidth * tileWidth - 200);
      const hw = 32 + rng() * 48;

      if (rng() < 0.35) {
        hazards.lava.push({ x: hx, y: (gridHeight - 2) * tileHeight, w: hw, h: tileHeight });
      } else if (rng() < 0.7) {
        hazards.water.push({ x: hx, y: (gridHeight - 2) * tileHeight, w: hw, h: tileHeight });
      } else {
        hazards.goo.push({ x: hx, y: (gridHeight - 2) * tileHeight, w: hw, h: tileHeight });
      }
    }
    state.write('hazard_zones', hazards);

    // Generate mechanisms
    const mechanisms = { levers: [], doors: [], buttons: [], platforms: [] };

    if (difficulty >= 3) {
      const numButtons = Math.min(Math.floor((difficulty - 2) / 2) + 1, 3);
      for (let i = 0; i < numButtons; i++) {
        mechanisms.buttons.push({
          id: 'button_' + i,
          x: 120 + i * 180,
          y: (gridHeight - 2) * tileHeight,
          width: 40,
          height: 8,
          pressed: false,
          targetDoor: 'door_' + i
        });

        mechanisms.doors.push({
          id: 'door_' + i,
          x: 200 + i * 200,
          y: (gridHeight - 5) * tileHeight,
          width: 16,
          height: 96,
          open: false,
          startY: (gridHeight - 5) * tileHeight,
          endY: (gridHeight - 5) * tileHeight - 80
        });
      }
    }

    if (difficulty >= 5) {
      const numLevers = Math.min(Math.floor((difficulty - 4) / 2) + 1, 2);
      for (let i = 0; i < numLevers; i++) {
        mechanisms.levers.push({
          id: 'lever_' + i,
          x: 180 + i * 250,
          y: (gridHeight - 4) * tileHeight,
          activated: false,
          targetPlatform: 'moving_platform_' + i
        });

        mechanisms.platforms.push({
          id: 'moving_platform_' + i,
          x: 220 + i * 250,
          y: (gridHeight - 6) * tileHeight,
          width: 80,
          height: 12,
          startX: 220 + i * 250,
          endX: 350 + i * 250,
          speed: 80,
          moving: false,
          direction: 1
        });
      }
    }
    state.write('mechanism_state', mechanisms);

    // Generate gems
    const gems = [];
    const numGems = 5 + difficulty;

    for (let i = 0; i < numGems; i++) {
      const gemType = rng() < 0.5 ? 'fire' : 'water';
      gems.push({
        id: 'gem_' + i,
        x: 80 + rng() * (gridWidth * tileWidth - 160),
        y: 80 + rng() * ((gridHeight - 4) * tileHeight),
        type: gemType,
        collected: false,
        bobOffset: rng() * Math.PI * 2
      });
    }

    state.write('gem_collection', {
      collected: [],
      total: numGems,
      gems: gems
    });

    // Set entity positions
    state.write('entity_positions', {
      fireboy: {
        x: spawnPoints.fireboy.x,
        y: spawnPoints.fireboy.y,
        vx: 0, vy: 0,
        onGround: false,
        facing: 1,
        animFrame: 0,
        animTime: 0,
        walking: false
      },
      watergirl: {
        x: spawnPoints.watergirl.x,
        y: spawnPoints.watergirl.y,
        vx: 0, vy: 0,
        onGround: false,
        facing: 1,
        animFrame: 0,
        animTime: 0,
        walking: false
      }
    });

    // Update player state
    const currentPlayerState = state.read('player_state') || {};
    state.write('player_state', {
      level: levelNum,
      score: currentPlayerState.score || 0,
      lives: currentPlayerState.lives || 3,
      levelStartTime: Date.now()
    });
  },

  seededRandom(seed) {
    return function() {
      seed = (seed * 9301 + 49297) % 233280;
      return seed / 233280;
    };
  }
};

export default level_generator;

const level_generator = {
  name: 'level_generator',

  init(state) {
    state.write('entity_positions', {
      fireboy: { 
        x: 100, y: 400, vx: 0, vy: 0, 
        onGround: false, facing: 1, 
        animFrame: 0, animTime: 0, walking: false,
        width: 28, height: 44
      },
      watergirl: { 
        x: 150, y: 400, vx: 0, vy: 0, 
        onGround: false, facing: -1, 
        animFrame: 0, animTime: 0, walking: false,
        width: 28, height: 44
      }
    });

    state.write('tile_layout', {
      tiles: [],
      width: 800,
      height: 480,
      tileSize: 32
    });

    state.write('hazard_zones', {
      lava: [],
      water: [],
      goo: []
    });

    state.write('mechanism_state', {
      levers: [],
      doors: [],
      buttons: [],
      platforms: []
    });

    state.write('gem_collection', {
      collected: [],
      total: 0,
      gems: []
    });

    state.write('player_state', {
      level: 1,
      score: 0,
      lives: 3,
      levelStartTime: Date.now()
    });
  },

  update(state, dt) {
    const game_state = state.read('game_state');
    const level_config = state.read('level_config');

    if (!game_state) return;

    if (game_state.status === 'loading' || game_state.needsLevelGeneration) {
      const levelNum = game_state.currentLevel || 1;
      this.generateLevel(state, level_config, levelNum);
    }

    // Update entity animation
    const entities = state.read('entity_positions');
    if (entities) {
      if (entities.fireboy.walking) {
        entities.fireboy.animTime += dt;
        entities.fireboy.animFrame = Math.floor(entities.fireboy.animTime * 8) % 4;
      }
      if (entities.watergirl.walking) {
        entities.watergirl.animTime += dt;
        entities.watergirl.animFrame = Math.floor(entities.watergirl.animTime * 8) % 4;
      }
      state.write('entity_positions', entities);
    }
  },

  generateLevel(state, config, levelNum) {
    const difficulty = config?.difficulty || Math.min(levelNum, 10);
    const seed = config?.seed || levelNum * 12345;
    const random = this.seededRandom(seed);

    const width = 800;
    const height = 480;
    const tileSize = 32;
    const cols = Math.floor(width / tileSize);
    const rows = Math.floor(height / tileSize);

    const tiles = this.generateTiles(cols, rows, difficulty, random);
    state.write('tile_layout', {
      tiles: tiles,
      width: width,
      height: height,
      tileSize: tileSize
    });

    const hazards = this.generateHazards(tiles, tileSize, cols, rows, difficulty, random);
    state.write('hazard_zones', hazards);

    const mechanisms = this.generateMechanisms(tiles, tileSize, cols, rows, difficulty, random);
    state.write('mechanism_state', mechanisms);

    const gems = this.generateGems(tiles, tileSize, cols, rows, difficulty, random);
    state.write('gem_collection', {
      collected: [],
      total: gems.length,
      gems: gems
    });

    const spawn = this.findSpawnPoint(tiles, tileSize, cols, rows);
    state.write('entity_positions', {
      fireboy: { 
        x: spawn.x, y: spawn.y - 44, vx: 0, vy: 0, 
        onGround: true, facing: 1, 
        animFrame: 0, animTime: 0, walking: false,
        width: 28, height: 44
      },
      watergirl: { 
        x: spawn.x + 50, y: spawn.y - 44, vx: 0, vy: 0, 
        onGround: true, facing: -1, 
        animFrame: 0, animTime: 0, walking: false,
        width: 28, height: 44
      }
    });

    state.write('player_state', {
      level: levelNum,
      score: 0,
      lives: 3,
      levelStartTime: Date.now()
    });
  },

  generateTiles(cols, rows, difficulty, random) {
    const tiles = [];
    for (let y = 0; y < rows; y++) {
      tiles[y] = [];
      for (let x = 0; x < cols; x++) {
        tiles[y][x] = 0;
      }
    }

    // Floor
    for (let x = 0; x < cols; x++) {
      tiles[rows - 1][x] = 1;
    }

    // Walls
    for (let y = 0; y < rows; y++) {
      tiles[y][0] = 1;
      tiles[y][cols - 1] = 1;
    }

    // Platforms with increasing complexity
    const platformCount = 2 + Math.floor(difficulty * 0.6);
    let lastY = rows - 4;

    for (let i = 0; i < platformCount; i++) {
      const px = 3 + Math.floor(random() * (cols - 10));
      const py = Math.max(3, lastY - 2 - Math.floor(random() * 2));
      lastY = py;
      const pwidth = 4 + Math.floor(random() * 4);

      for (let dx = 0; dx < pwidth && px + dx < cols - 2; dx++) {
        if (random() > 0.15) {
          tiles[py][px + dx] = 1;
        }
      }
    }

    // Add some vertical walls for puzzle elements
    if (difficulty > 2) {
      const wallCount = Math.floor(difficulty * 0.3);
      for (let i = 0; i < wallCount; i++) {
        const wx = 5 + Math.floor(random() * (cols - 10));
        const wy = rows - 4;
        const wheight = 2 + Math.floor(random() * 3);

        for (let dy = 0; dy < wheight; dy++) {
          if (rows - 2 - dy >= 0) {
            tiles[rows - 2 - dy][wx] = 1;
          }
        }
      }
    }

    // Ensure solvability - clear path near spawn
    for (let x = 1; x < 6; x++) {
      for (let y = rows - 4; y < rows - 1; y++) {
        tiles[y][x] = 0;
      }
    }

    return tiles;
  },

  generateHazards(tiles, tileSize, cols, rows, difficulty, random) {
    const hazards = { lava: [], water: [], goo: [] };

    // Lava pools (safe for Fireboy)
    const lavaCount = Math.ceil(difficulty * 0.4);
    for (let i = 0; i < lavaCount; i++) {
      const lx = 8 + Math.floor(random() * (cols - 12));
      hazards.lava.push({
        x: lx * tileSize,
        y: (rows - 1) * tileSize - 6,
        width: (2 + Math.floor(random() * 2)) * tileSize,
        height: 6
      });
    }

    // Water pools (safe for Watergirl)
    const waterCount = Math.ceil(difficulty * 0.4);
    for (let i = 0; i < waterCount; i++) {
      const wx = 8 + Math.floor(random() * (cols - 12));
      hazards.water.push({
        x: wx * tileSize,
        y: (rows - 1) * tileSize - 6,
        width: (2 + Math.floor(random() * 2)) * tileSize,
        height: 6
      });
    }

    // Goo pools (deadly to both) - appears at higher difficulty
    if (difficulty >= 3) {
      const gooCount = Math.floor((difficulty - 2) * 0.3);
      for (let i = 0; i < gooCount; i++) {
        const gx = 10 + Math.floor(random() * (cols - 14));
        hazards.goo.push({
          x: gx * tileSize,
          y: (rows - 1) * tileSize - 6,
          width: (1 + Math.floor(random() * 2)) * tileSize,
          height: 6
        });
      }
    }

    return hazards;
  },

  generateMechanisms(tiles, tileSize, cols, rows, difficulty, random) {
    const mechanisms = { levers: [], doors: [], buttons: [], platforms: [] };

    if (difficulty >= 2) {
      mechanisms.levers.push({
        id: 'lever_1',
        x: 180 + Math.floor(random() * 200),
        y: (rows - 2) * tileSize,
        activated: false,
        linkedDoor: 'door_1'
      });

      mechanisms.doors.push({
        id: 'door_1',
        x: 550 + Math.floor(random() * 100),
        y: (rows - 3) * tileSize,
        open: false,
        width: 32,
        height: 64
      });
    }

    if (difficulty >= 4) {
      mechanisms.buttons.push({
        id: 'button_1',
        x: 300 + Math.floor(random() * 150),
        y: (rows - 2) * tileSize,
        pressed: false,
        linkedPlatform: 'platform_1'
      });

      mechanisms.platforms.push({
        id: 'platform_1',
        x: 400,
        y: 280,
        width: 96,
        height: 12,
        startX: 350,
        endX: 550,
        speed: 60,
        direction: 1,
        active: false
      });
    }

    if (difficulty >= 6) {
      mechanisms.levers.push({
        id: 'lever_2',
        x: 500 + Math.floor(random() * 100),
        y: (rows - 5) * tileSize,
        activated: false,
        linkedDoor: 'door_2'
      });

      mechanisms.doors.push({
        id: 'door_2',
        x: 250,
        y: (rows - 5) * tileSize,
        open: false,
        width: 32,
        height: 64
      });
    }

    return mechanisms;
  },

  generateGems(tiles, tileSize, cols, rows, difficulty, random) {
    const gems = [];
    const gemCount = 4 + Math.floor(difficulty * 0.8);

    for (let i = 0; i < gemCount; i++) {
      const type = i % 2 === 0 ? 'fire' : 'water';
      const gx = 4 + Math.floor(random() * (cols - 6));
      const gy = 2 + Math.floor(random() * (rows - 4));

      gems.push({
        id: `gem_${i}`,
        x: gx * tileSize + tileSize / 2,
        y: gy * tileSize + tileSize / 2,
        type: type,
        collected: false
      });
    }

    return gems;
  },

  findSpawnPoint(tiles, tileSize, cols, rows) {
    for (let x = 2; x < cols / 4; x++) {
      if (tiles[rows - 2][x] === 0) {
        return { x: x * tileSize + tileSize / 2, y: (rows - 1) * tileSize };
      }
    }
    return { x: 120, y: 416 };
  },

  seededRandom(seed) {
    let s = seed;
    return function() {
      s = (s * 1103515245 + 12345) & 0x7fffffff;
      return s / 0x7fffffff;
    };
  },

  render(state, ctx) {
    const tile_layout = state.read('tile_layout');
    if (!tile_layout || !tile_layout.tiles || tile_layout.tiles.length === 0) return;

    const tiles = tile_layout.tiles;
    const tileSize = tile_layout.tileSize || 32;

    // Draw tiles
    for (let y = 0; y < tiles.length; y++) {
      for (let x = 0; x < tiles[y].length; x++) {
        if (tiles[y][x] === 1) {
          const gradient = ctx.createLinearGradient(
            x * tileSize, y * tileSize,
            x * tileSize, (y + 1) * tileSize
          );
          gradient.addColorStop(0, '#6b5b4f');
          gradient.addColorStop(1, '#4a3f35');
          ctx.fillStyle = gradient;
          ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);

          ctx.strokeStyle = '#3a2f25';
          ctx.lineWidth = 1;
          ctx.strokeRect(x * tileSize + 0.5, y * tileSize + 0.5, tileSize - 1, tileSize - 1);
        }
      }
    }

    // Draw hazards
    const hazards = state.read('hazard_zones');
    if (hazards) {
      // Lava
      hazards.lava.forEach(h => {
        const gradient = ctx.createLinearGradient(h.x, h.y, h.x, h.y + h.height);
        gradient.addColorStop(0, '#ff6600');
        gradient.addColorStop(0.5, '#ff3300');
        gradient.addColorStop(1, '#cc1100');
        ctx.fillStyle = gradient;
        ctx.fillRect(h.x, h.y, h.width, h.height);

        // Glow effect
        ctx.shadowColor = '#ff4400';
        ctx.shadowBlur = 10;
        ctx.fillRect(h.x, h.y, h.width, h.height);
        ctx.shadowBlur = 0;
      });

      // Water
      hazards.water.forEach(h => {
        const gradient = ctx.createLinearGradient(h.x, h.y, h.x, h.y + h.height);
        gradient.addColorStop(0, '#4488ff');
        gradient.addColorStop(0.5, '#2266dd');
        gradient.addColorStop(1, '#0044bb');
        ctx.fillStyle = gradient;
        ctx.fillRect(h.x, h.y, h.width, h.height);

        ctx.shadowColor = '#0066ff';
        ctx.shadowBlur = 8;
        ctx.fillRect(h.x, h.y, h.width, h.height);
        ctx.shadowBlur = 0;
      });

      // Goo
      hazards.goo.forEach(h => {
        const gradient = ctx.createLinearGradient(h.x, h.y, h.x, h.y + h.height);
        gradient.addColorStop(0, '#55aa33');
        gradient.addColorStop(1, '#336611');
        ctx.fillStyle = gradient;
        ctx.fillRect(h.x, h.y, h.width, h.height);
      });
    }

    // Draw mechanisms
    const mechanisms = state.read('mechanism_state');
    if (mechanisms) {
      // Doors
      mechanisms.doors.forEach(door => {
        ctx.fillStyle = door.open ? '#2a4a2a' : '#8b4513';
        ctx.fillRect(door.x, door.y, door.width, door.height);
        if (!door.open) {
          ctx.strokeStyle = '#5d2906';
          ctx.lineWidth = 2;
          ctx.strokeRect(door.x, door.y, door.width, door.height);
        }
      });

      // Levers
      mechanisms.levers.forEach(lever => {
        ctx.fillStyle = '#666666';
        ctx.fillRect(lever.x - 8, lever.y - 16, 16, 20);
        ctx.fillStyle = lever.activated ? '#00ff00' : '#ff0000';
        ctx.beginPath();
        ctx.arc(lever.x, lever.y - 20 + (lever.activated ? 8 : -8), 6, 0, Math.PI * 2);
        ctx.fill();
      });

      // Platforms
      mechanisms.platforms.forEach(plat => {
        ctx.fillStyle = plat.active ? '#887766' : '#555555';
        ctx.fillRect(plat.x, plat.y, plat.width, plat.height);
        ctx.strokeStyle = '#444444';
        ctx.strokeRect(plat.x, plat.y, plat.width, plat.height);
      });
    }

    // Draw gems
    const gemCollection = state.read('gem_collection');
    if (gemCollection && gemCollection.gems) {
      gemCollection.gems.forEach(gem => {
        if (!gem.collected) {
          ctx.save();
          ctx.translate(gem.x, gem.y);

          const time = Date.now() * 0.003;
          ctx.rotate(Math.sin(time + gem.x) * 0.1);

          ctx.beginPath();
          ctx.moveTo(0, -12);
          ctx.lineTo(8, 0);
          ctx.lineTo(0, 12);
          ctx.lineTo(-8, 0);
          ctx.closePath();

          ctx.fillStyle = gem.type === 'fire' ? '#ff8800' : '#00ccff';
          ctx.fill();
          ctx.strokeStyle = gem.type === 'fire' ? '#ff4400' : '#0088cc';
          ctx.lineWidth = 2;
          ctx.stroke();

          // Inner glow
          ctx.fillStyle = gem.type === 'fire' ? '#ffcc00' : '#66ddff';
          ctx.beginPath();
          ctx.moveTo(0, -6);
          ctx.lineTo(4, 0);
          ctx.lineTo(0, 6);
          ctx.lineTo(-4, 0);
          ctx.closePath();
          ctx.fill();

          ctx.restore();
        }
      });
    }

    // Draw characters
    const entities = state.read('entity_positions');
    if (entities) {
      this.drawCharacter(ctx, entities.fireboy, 'fire');
      this.drawCharacter(ctx, entities.watergirl, 'water');
    }
  },

  drawCharacter(ctx, entity, type) {
    if (!entity) return;

    const x = entity.x;
    const y = entity.y;
    const w = entity.width || 28;
    const h = entity.height || 44;
    const frame = entity.animFrame || 0;
    const facing = entity.facing || 1;

    ctx.save();
    ctx.translate(x, y);
    if (facing < 0) ctx.scale(-1, 1);

    const isFire = type === 'fire';
    const mainColor = isFire ? '#ff6622' : '#22aaff';
    const darkColor = isFire ? '#cc3300' : '#0077cc';
    const lightColor = isFire ? '#ffaa44' : '#66ddff';

    // Legs with walking animation
    const legOffset = entity.walking ? Math.sin(frame * 1.57) * 4 : 0;
    ctx.fillStyle = darkColor;
    ctx.fillRect(-8, -10 + legOffset, 5, 10);
    ctx.fillRect(3, -10 - legOffset, 5, 10);

    // Body
    ctx.fillStyle = mainColor;
    ctx.beginPath();
    ctx.ellipse(0, -h/2, w/2.2, h/2.8, 0, 0, Math.PI * 2);
    ctx.fill();

    // Body highlight
    ctx.fillStyle = lightColor;
    ctx.beginPath();
    ctx.ellipse(-3, -h/2 - 5, w/6, h/5, -0.3, 0, Math.PI * 2);
    ctx.fill();

    // Head
    ctx.fillStyle = mainColor;
    ctx.beginPath();
    ctx.arc(0, -h + 12, w/2.3, 0, Math.PI * 2);
    ctx.fill();

    // Head highlight
    ctx.fillStyle = lightColor;
    ctx.beginPath();
    ctx.arc(-3, -h + 10, w/5, 0, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.ellipse(-5, -h + 10, 4, 5, 0, 0, Math.PI * 2);
    ctx.ellipse(5, -h + 10, 4, 5, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#222222';
    ctx.beginPath();
    ctx.arc(-4, -h + 11, 2, 0, Math.PI * 2);
    ctx.arc(6, -h + 11, 2, 0, Math.PI * 2);
    ctx.fill();

    // Element effect on head
    if (isFire) {
      // Flame effect
      const flameTime = Date.now() * 0.01;
      ctx.fillStyle = '#ffcc00';
      for (let i = 0; i < 4; i++) {
        const fx = Math.sin(flameTime + i * 2) * 4;
        const fy = -h - 2 - Math.abs(Math.sin(flameTime * 1.5 + i)) * 8;
        ctx.beginPath();
        ctx.moveTo(fx - 3, fy + 6);
        ctx.quadraticCurveTo(fx, fy - 4, fx + 3, fy + 6);
        ctx.fill();
      }
    } else {
      // Frost/ice crystal effect
      const frostTime = Date.now() * 0.008;
      ctx.fillStyle = '#aaeeff';
      ctx.strokeStyle = '#66ccff';
      ctx.lineWidth = 1;
      for (let i = 0; i < 3; i++) {
        const angle = frostTime + i * 2.1;
        const fx = Math.cos(angle) * 8;
        const fy = -h - 4 - Math.abs(Math.sin(frostTime + i)) * 4;
        ctx.beginPath();
        ctx.moveTo(fx, fy - 4);
        ctx.lineTo(fx + 3, fy);
        ctx.lineTo(fx, fy + 2);
        ctx.lineTo(fx - 3, fy);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
      }
    }

    // Outline
    ctx.strokeStyle = darkColor;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(0, -h/2, w/2.2, h/2.8, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, -h + 12, w/2.3, 0, Math.PI * 2);
    ctx.stroke();

    ctx.restore();
  }
};

