const mechanism_controller = {
  name: 'mechanism_controller',

  init(state) {
    state.write('mechanism_state', {
      buttons: [
        { id: 'btn1', x: 180, y: 388, width: 50, height: 12, isPressed: false, type: 'fire' },
        { id: 'btn2', x: 380, y: 388, width: 50, height: 12, isPressed: false, type: 'water' },
        { id: 'btn3', x: 580, y: 288, width: 50, height: 12, isPressed: false, type: 'any' }
      ],
      doors: [
        { id: 'door1', x: 280, y: 300, width: 25, height: 100, isOpen: false, linkedButtons: ['btn1'], openAmount: 0 },
        { id: 'door2', x: 480, y: 300, width: 25, height: 100, isOpen: false, linkedButtons: ['btn2'], openAmount: 0 },
        { id: 'door3', x: 680, y: 200, width: 25, height: 100, isOpen: false, linkedButtons: ['btn3'], openAmount: 0 }
      ],
      platforms: [
        { id: 'plat1', x: 300, y: 220, width: 120, height: 18, startX: 300, endX: 500, speed: 60, direction: 1, vertical: false },
        { id: 'plat2', x: 520, y: 160, width: 100, height: 18, startY: 160, endY: 280, speed: 45, direction: 1, vertical: true }
      ],
      boxes: [
        { id: 'box1', x: 220, y: 356, width: 35, height: 35, vx: 0, vy: 0, grounded: true }
      ],
      fireboy: { x: 100, y: 360, width: 28, height: 45, animFrame: 0 },
      watergirl: { x: 140, y: 360, width: 28, height: 45, animFrame: 0 },
      time: 0
    });
  },

  update(state, dt) {
    const entityPositions = state.read('entity_positions');
    const mechState = state.read('mechanism_state');

    if (!mechState) return;

    const newMechState = JSON.parse(JSON.stringify(mechState));
    newMechState.time += dt;

    const fireboy = entityPositions?.fireboy || newMechState.fireboy;
    const watergirl = entityPositions?.watergirl || newMechState.watergirl;

    if (entityPositions?.fireboy) {
      newMechState.fireboy = { ...entityPositions.fireboy, animFrame: newMechState.time };
    }
    if (entityPositions?.watergirl) {
      newMechState.watergirl = { ...entityPositions.watergirl, animFrame: newMechState.time };
    }

    // Update buttons - check collision with players
    newMechState.buttons.forEach(button => {
      button.isPressed = false;

      const players = [fireboy, watergirl].filter(p => p);
      players.forEach(player => {
        const px = player.x || 0;
        const py = player.y || 0;
        const pw = player.width || 28;
        const ph = player.height || 45;

        const onButton = px + pw > button.x && px < button.x + button.width &&
                        py + ph >= button.y - 8 && py + ph <= button.y + button.height + 5;

        if (onButton) {
          if (button.type === 'any') {
            button.isPressed = true;
          } else if (button.type === 'fire' && player === fireboy) {
            button.isPressed = true;
          } else if (button.type === 'water' && player === watergirl) {
            button.isPressed = true;
          }
        }
      });

      // Also check boxes on buttons
      newMechState.boxes.forEach(box => {
        const onButton = box.x + box.width > button.x && box.x < button.x + button.width &&
                        box.y + box.height >= button.y - 5 && box.y + box.height <= button.y + 15;
        if (onButton && button.type === 'any') {
          button.isPressed = true;
        }
      });
    });

