    newMechState.doors.forEach(door => {
      door.isOpen = door.linkedButtons.some(btnId => {
        const btn = newMechState.buttons.find(b => b.id === btnId);
        return btn && btn.isPressed;
      });

      const targetAmount = door.isOpen ? 1 : 0;
      door.openAmount += (targetAmount - door.openAmount) * 5 * dt;
    });

