    newMechState.platforms.forEach(platform => {
      if (platform.vertical) {
        platform.y += platform.speed * dt * platform.direction;
        if (platform.y >= platform.endY || platform.y <= platform.startY) {
          platform.direction *= -1;
          platform.y = Math.max(platform.startY, Math.min(platform.endY, platform.y));
        }
