        { id: 'door2', x: 480, y: 300, width: 25, height: 100, isOpen: false, linkedButtons: ['btn2'], openAmount: 0 },
        { id: 'door3', x: 680, y: 200, width: 25, height: 100, isOpen: false, linkedButtons: ['btn3'], openAmount: 0 }
      ],
      platforms: [
        { id: 'plat1', x: 300, y: 220, width: 120, height: 18, startX: 300, endX: 500, speed: 60, direction: 1, vertical: false },
        { id: 'plat2', x: 520, y: 160, width: 100, height: 18, startY: 160, endY: 280, speed: 45, direction: 1, vertical: true }
      ],
      boxes: [
        { id: 'box1', x: 220, y: 356, width: 35, height: 35, vx: 0, vy: 0 }
      ],
      time: 0
    });
  },

  update(state, dt) {
    const entityPositions = state.read('entity_positions');
    const mechState = state.read('mechanism_state');

    if (!mechState) return;

    mechState.time += dt;

    const fireboy = entityPositions && entityPositions.fireboy ? entityPositions.fireboy : { x: 100, y: 360, width: 28, height: 45 };
    const watergirl = entityPositions && entityPositions.watergirl ? entityPositions.watergirl : { x: 140, y: 360, width: 28, height: 45 };

    const checkOnButton = function(entity, button) {
      return entity.x < button.x + button.width &&
             entity.x + entity.width > button.x &&
             entity.y + entity.height >= button.y - 5 &&
             entity.y + entity.height <= button.y + button.height + 10;
    };

    mechState.buttons.forEach(function(button) {
      button.isPressed = false;

      if (button.type === 'fire' || button.type === 'any') {
        if (checkOnButton(fireboy, button)) {
          button.isPressed = true;
        }
      }

      if (button.type === 'water' || button.type === 'any') {
        if (checkOnButton(watergirl, button)) {
          button.isPressed = true;
        }
      }

      if (button.type === 'any') {
        mechState.boxes.forEach(function(box) {
          if (checkOnButton(box, button)) {
            button.isPressed = true;
          }
        });
      }
    });

    mechState.doors.forEach(function(door) {
      const anyPressed = door.linkedButtons.some(function(btnId) {
        const btn = mechState.buttons.find(function(b) { return b.id === btnId; });
        return btn && btn.isPressed;
      });

      door.isOpen = anyPressed;

      if (door.isOpen && door.openAmount < 1) {
        door.openAmount = Math.min(1, door.openAmount + dt * 3);
      } else if (!door.isOpen && door.openAmount > 0) {
        door.openAmount = Math.max(0, door.openAmount - dt * 3);
      }
    });

    mechState.platforms.forEach(function(platform) {
      if (platform.vertical) {
        platform.y += platform.speed * platform.direction * dt;
        if (platform.y >= platform.endY) {
          platform.direction = -1;
          platform.y = platform.endY;
        } else if (platform.y <= platform.startY) {
          platform.direction = 1;
          platform.y = platform.startY;
        }
      } else {
        platform.x += platform.speed * platform.direction * dt;
        if (platform.x >= platform.endX) {
          platform.direction = -1;
          platform.x = platform.endX;
        } else if (platform.x <= platform.startX) {
          platform.direction = 1;
          platform.x = platform.startX;
        }
      }
    });

    state.write('mechanism_state', mechState);
  },

  render(state, ctx) {
    const mechState = state.read('mechanism_state');
    if (!mechState) return;

    mechState.buttons.forEach(function(button) {
      ctx.fillStyle = button.isPressed ? '#555' : '#777';
      ctx.fillRect(button.x, button.y, button.width, button.height);

      if (button.type === 'fire') {
        ctx.fillStyle = '#ff6600';
      } else if (button.type === 'water') {
        ctx.fillStyle = '#00aaff';
      } else {
        ctx.fillStyle = '#aaaaaa';
      }

      ctx.beginPath();
      ctx.arc(button.x + button.width / 2, button.y - 4, 6, 0, Math.PI * 2);
      ctx.fill();
    });

    mechState.doors.forEach(function(door) {
      const visibleHeight = door.height * (1 - door.openAmount);

      ctx.fillStyle = '#4a3520';
      ctx.fillRect(door.x, door.y, door.width, door.height);

      ctx.fillStyle = '#3a2510';
      ctx.fillRect(door.x, door.y + door.height - visibleHeight, door.width, visibleHeight);

      ctx.strokeStyle = '#5a4530';
      ctx.lineWidth = 3;
      ctx.strokeRect(door.x - 2, door.y - 2, door.width + 4, door.height + 4);
    });

    mechState.platforms.forEach(function(platform) {
      const gradient = ctx.createLinearGradient(platform.x, platform.y, platform.x, platform.y + platform.height);
      gradient.addColorStop(0, '#8899aa');
      gradient.addColorStop(1, '#556677');
      ctx.fillStyle = gradient;
      ctx.fillRect(platform.x, platform.y, platform.width, platform.height);

      ctx.strokeStyle = '#aabbcc';
      ctx.lineWidth = 2;
      ctx.strokeRect(platform.x, platform.y, platform.width, platform.height);

      for (let i = 0; i < 3; i++) {
        ctx.fillStyle = '#445566';
        ctx.fillRect(platform.x + 10 + i * 35, platform.y + 4, 20, 3);
      }
    });

    mechState.boxes.forEach(function(box) {
      ctx.fillStyle = '#8b6914';
      ctx.fillRect(box.x, box.y, box.width, box.height);

      ctx.strokeStyle = '#5a4510';
      ctx.lineWidth = 3;
      ctx.strokeRect(box.x, box.y, box.width, box.height);

      ctx.strokeStyle = '#a08030';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(box.x + 5, box.y + 5);
      ctx.lineTo(box.x + box.width - 5, box.y + box.height - 5);
      ctx.moveTo(box.x + box.width - 5, box.y + 5);
      ctx.lineTo(box.x + 5, box.y + box.height - 5);
      ctx.stroke();
    });
  }
};

