const watergirl = {
  name: 'watergirl',

  keys: {
    left: false,
    right: false,
    up: false
  },

  init(state) {
    // Set up arrow key listeners
    const keyHandler = (e, pressed) => {
      if (e.key === 'ArrowLeft') { this.keys.left = pressed; e.preventDefault(); }
      if (e.key === 'ArrowRight') { this.keys.right = pressed; e.preventDefault(); }
      if (e.key === 'ArrowUp') { this.keys.up = pressed; e.preventDefault(); }
    };

    window.addEventListener('keydown', (e) => keyHandler(e, true));
    window.addEventListener('keyup', (e) => keyHandler(e, false));

    // Initialize player state
    state.write('player_state', {
      type: 'watergirl',
      x: 150,
      y: 300,
      vx: 0,
      vy: 0,
      width: 32,
      height: 48,
      onGround: false,
      alive: true,
      animationFrame: 0,
      facing: 1,
      walking: false,
      spawnX: 150,
      spawnY: 300
    });

    // Initialize gem collection
    state.write('gem_collection', {
      watergirlGems: 0,
      collectedIds: []
    });
  },

  update(state, dt) {
    const player = state.read('player_state');
    if (!player) return;

    if (!player.alive) {
      // Respawn after delay
      player.respawnTimer = (player.respawnTimer || 0) + dt;
      if (player.respawnTimer > 1.5) {
        player.alive = true;
        player.x = player.spawnX;
        player.y = player.spawnY;
        player.vx = 0;
        player.vy = 0;
        player.respawnTimer = 0;
      }
      state.write('player_state', player);
      return;
    }

    const hazards = state.read('hazard_zones') || [];
    const entities = state.read('entity_positions') || {};

    const speed = 180;
    const jumpForce = -420;
    const gravity = 900;
    const friction = 0.85;

    let walking = false;

    // Horizontal movement
    if (this.keys.left) {
      player.vx = -speed;
      player.facing = -1;
      walking = true;
    } else if (this.keys.right) {
      player.vx = speed;
      player.facing = 1;
      walking = true;
    } else {
      player.vx *= friction;
    }

    // Jump
    if (this.keys.up && player.onGround) {
      player.vy = jumpForce;
      player.onGround = false;
    }

    // Apply gravity
    player.vy += gravity * dt;
    player.vy = Math.min(player.vy, 600);

    // Update position
    player.x += player.vx * dt;
    player.y += player.vy * dt;

    // Simple ground check (canvas bottom)
    const groundLevel = 500;
    if (player.y + player.height >= groundLevel) {
      player.y = groundLevel - player.height;
      player.vy = 0;
      player.onGround = true;
    }

    // Platform collision from entities
    const platforms = entities.platforms || [];
    for (const plat of platforms) {
      if (this.boxCollision(
        player.x, player.y, player.width, player.height,
        plat.x, plat.y, plat.width, plat.height
      )) {
        // Landing on top
        if (player.vy > 0 && player.y + player.height - player.vy * dt <= plat.y + 5) {
          player.y = plat.y - player.height;
          player.vy = 0;
          player.onGround = true;
        }
      }
    }

    // Screen bounds
    player.x = Math.max(0, Math.min(player.x, 800 - player.width));

    // Animation update
    player.walking = walking && player.onGround;
    if (player.walking) {
      player.animationFrame += dt * 12;
    } else {
      player.animationFrame = 0;
    }

    // Hazard collision
    for (const hazard of hazards) {
      if (this.boxCollision(
        player.x, player.y, player.width, player.height,
        hazard.x, hazard.y, hazard.width, hazard.height
      )) {
        if (hazard.type === 'lava' || hazard.type === 'fire') {
          player.alive = false;
        }
        // Water pools are safe for watergirl
      }
    }

    // Gem collection
    const gems = entities.gems || [];
    const gemData = state.read('gem_collection') || { watergirlGems: 0, collectedIds: [] };

    for (const gem of gems) {
      if (gem.color === 'blue' || gem.type === 'blue' || gem.owner === 'watergirl') {
        if (this.boxCollision(
          player.x, player.y, player.width, player.height,
          gem.x, gem.y, gem.size || 16, gem.size || 16
        )) {
          const gemId = gem.id || `${gem.x}_${gem.y}`;
          if (!gemData.collectedIds.includes(gemId)) {
            gemData.watergirlGems++;
            gemData.collectedIds.push(gemId);
          }
        }
      }
    }

    state.write('player_state', player);
    state.write('gem_collection', gemData);
  },

  boxCollision(x1, y1, w1, h1, x2, y2, w2, h2) {
    return x1 < x2 + w2 && x1 + w1 > x2 && y1 < y2 + h2 && y1 + h1 > y2;
  },

