    // Body gradient (blue frost spirit)
    const bodyGrad = ctx.createLinearGradient(0, 8 - bounce, 0, height - 12 - bounce);
    bodyGrad.addColorStop(0, '#4fc3f7');
    bodyGrad.addColorStop(0.5, '#039be5');
    bodyGrad.addColorStop(1, '#01579b');

    ctx.fillStyle = bodyGrad;

    // Body
    ctx.beginPath();
    ctx.moveTo(width / 2 - 12, height - 14 - bounce);
    ctx.quadraticCurveTo(width / 2 - 14, height / 2, width / 2 - 10, 20 - bounce);
    ctx.quadraticCurveTo(width / 2, 10 - bounce, width / 2 + 10, 20 - bounce);
    ctx.quadraticCurveTo(width / 2 + 14, height / 2, width / 2 + 12, height - 14 - bounce);
    ctx.quadraticCurveTo(width / 2, height - 10 - bounce, width / 2 - 12, height - 14 - bounce);
    ctx.fill();

    // Head
    ctx.beginPath();
    ctx.arc(width / 2, 14 - bounce, 13, 0, Math.PI * 2);
    ctx.fill();

    // Hair/crystal spikes
    ctx.fillStyle = '#b3e5fc';
    const spikes = [-8, 0, 8];
    spikes.forEach((offset, i) => {
      ctx.beginPath();
      ctx.moveTo(width / 2 + offset - 3, 8 - bounce);
      ctx.lineTo(width / 2 + offset, -2 - bounce + Math.sin(time + i) * 2);
      ctx.lineTo(width / 2 + offset + 3, 8 - bounce);
      ctx.fill();
    });

    // Face
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.ellipse(width / 2 - 5, 12 - bounce, 3.5, 4, 0, 0, Math.PI * 2);
    ctx.ellipse(width / 2 + 5, 12 - bounce, 3.5, 4, 0, 0, Math.PI * 2);
    ctx.fill();

    // Pupils
    ctx.fillStyle = '#1a237e';
    const pupilOffset = walking ? Math.sin(animationFrame * 0.5) : 0;
    ctx.beginPath();
    ctx.arc(width / 2 - 5 + pupilOffset, 13 - bounce, 2, 0, Math.PI * 2);
    ctx.arc(width / 2 + 5 + pupilOffset, 13 - bounce, 2, 0, Math.PI * 2);
    ctx.fill();

    // Smile
    ctx.strokeStyle = '#01579b';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(width / 2, 17 - bounce, 4, 0.1 * Math.PI, 0.9 * Math.PI);
    ctx.stroke();

    // Arms
    ctx.fillStyle = '#039be5';
    const armSwing = walking ? Math.sin(animationFrame) * 0.4 : 0;

    ctx.save();
    ctx.translate(width / 2 - 12, 26 - bounce);
    ctx.rotate(-armSwing);
    ctx.fillRect(-4, 0, 5, 12);
    ctx.restore();

    ctx.save();
    ctx.translate(width / 2 + 12, 26 - bounce);
    ctx.rotate(armSwing);
    ctx.fillRect(-1, 0, 5, 12);
    ctx.restore();

    // Frost particles
    ctx.fillStyle = 'rgba(179, 229, 252, 0.7)';
    for (let i = 0; i < 4; i++) {
      const px = width / 2 + Math.cos(time * 1.3 + i * 1.57) * 18;
      const py = height / 2 + Math.sin(time * 1.3 + i * 1.57) * 20;
      ctx.beginPath();
      ctx.arc(px, py, 2 + Math.sin(time + i) * 1, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();

    // Death effect
    if (!alive) {
      ctx.fillStyle = 'rgba(255, 82, 82, 0.5)';
      ctx.beginPath();
      ctx.arc(x + width / 2, y + height / 2, 30, 0, Math.PI * 2);
      ctx.fill();
    }
  }
};

export default watergirl;

const watergirl = {
  name: 'watergirl',

  keys: {
    left: false,
    right: false,
    up: false
  },

  init(state) {
    const keyHandler = (e, pressed) => {
      if (e.key === 'ArrowLeft') { this.keys.left = pressed; e.preventDefault(); }
      if (e.key === 'ArrowRight') { this.keys.right = pressed; e.preventDefault(); }
      if (e.key === 'ArrowUp') { this.keys.up = pressed; e.preventDefault(); }
    };

    window.addEventListener('keydown', (e) => keyHandler(e, true));
    window.addEventListener('keyup', (e) => keyHandler(e, false));

    state.write('player_state', {
      type: 'watergirl',
      x: 150,
      y: 300,
      vx: 0,
      vy: 0,
      width: 32,
      height: 48,
      onGround: false,
      alive: true,
      animationFrame: 0,
      animationTimer: 0,
      facing: 1,
      walking: false,
      spawnX: 150,
      spawnY: 300,
      respawnTimer: 0
    });

    state.write('gem_collection', {
      watergirlGems: 0,
      collectedIds: []
    });
  },

  update(state, dt) {
    let player = state.read('player_state');
    if (!player) return;

    if (!player.alive) {
      player.respawnTimer += dt;
      if (player.respawnTimer > 1.5) {
        player.alive = true;
        player.x = player.spawnX;
        player.y = player.spawnY;
        player.vx = 0;
        player.vy = 0;
        player.respawnTimer = 0;
      }
      state.write('player_state', player);
      return;
    }

    const moveSpeed = 180;
    const jumpForce = -420;
    const gravity = 900;

    player.walking = false;
    if (this.keys.left) {
      player.vx = -moveSpeed;
      player.facing = -1;
      player.walking = true;
    } else if (this.keys.right) {
      player.vx = moveSpeed;
      player.facing = 1;
      player.walking = true;
    } else {
      player.vx = 0;
    }

    if (this.keys.up && player.onGround) {
      player.vy = jumpForce;
      player.onGround = false;
    }

    player.vy += gravity * dt;
    player.vy = Math.min(player.vy, 500);

    player.x += player.vx * dt;
    player.y += player.vy * dt;

    player.onGround = false;
    if (player.y > 450) {
      player.y = 450;
      player.vy = 0;
      player.onGround = true;
    }

    player.x = Math.max(0, Math.min(player.x, 768));

    player.animationTimer += dt;
    if (player.animationTimer > 0.1) {
      player.animationTimer = 0;
      player.animationFrame = (player.animationFrame + 1) % 4;
    }

    const hazards = state.read('hazard_zones');
    if (hazards) {
      for (const hazard of hazards) {
        if (this.checkCollision(player, hazard)) {
          if (hazard.type === 'lava') {
            player.alive = false;
            player.respawnTimer = 0;
          }
        }
      }
    }

    const entities = state.read('entity_positions');
    let gemCollection = state.read('gem_collection');
    if (entities && entities.gems) {
      for (const gem of entities.gems) {
        if (gem.color === 'blue' && this.checkCollision(player, gem)) {
          const gemId = gem.id || `gem_${gem.x}_${gem.y}`;
          if (!gemCollection.collectedIds.includes(gemId)) {
            gemCollection.watergirlGems++;
            gemCollection.collectedIds.push(gemId);
          }
        }
      }
    }

    state.write('player_state', player);
    state.write('gem_collection', gemCollection);
  },

  checkCollision(a, b) {
    const bw = b.width || 24;
    const bh = b.height || 24;
    return a.x < b.x + bw && a.x + a.width > b.x &&
           a.y < b.y + bh && a.y + a.height > b.y;
  },

  render(state, ctx) {
    const player = state.read('player_state');
    if (!player) return;

    ctx.save();

    if (!player.alive) {
      if (Math.floor(player.respawnTimer * 8) % 2 === 0) {
        ctx.globalAlpha = 0.3;
      }
    }

    const x = player.x;
    const y = player.y;
    const w = player.width;
    const h = player.height;

    const frostPulse = Math.sin(Date.now() / 300) * 2;

    ctx.fillStyle = '#4FC3F7';
    ctx.fillRect(x + 4, y + 14, w - 8, h - 18);

    ctx.fillStyle = '#81D4FA';
    ctx.beginPath();
    ctx.arc(x + w/2, y + 12, 11, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#29B6F6';
    ctx.beginPath();
    ctx.moveTo(x + w/2, y - 4 + frostPulse);
    ctx.lineTo(x + w/2 - 8, y + 10);
    ctx.lineTo(x + w/2 + 8, y + 10);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(x + 4, y + 2 - frostPulse);
    ctx.lineTo(x + 2, y + 12);
    ctx.lineTo(x + 10, y + 10);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(x + w - 4, y + 2 - frostPulse);
    ctx.lineTo(x + w - 2, y + 12);
    ctx.lineTo(x + w - 10, y + 10);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#01579B';
    const eyeOffsetX = player.facing > 0 ? 0 : -2;
    ctx.fillRect(x + w/2 - 6 + eyeOffsetX, y + 10, 3, 4);
    ctx.fillRect(x + w/2 + 3 + eyeOffsetX, y + 10, 3, 4);

    ctx.fillStyle = '#B3E5FC';
    ctx.fillRect(x + w/2 - 5 + eyeOffsetX, y + 11, 1, 1);
    ctx.fillRect(x + w/2 + 4 + eyeOffsetX, y + 11, 1, 1);

    ctx.fillStyle = '#0288D1';
    if (player.walking) {
      const legAnim = Math.sin(player.animationFrame * Math.PI / 2) * 5;
      ctx.fillRect(x + 8, y + h - 14 + legAnim, 7, 14);
      ctx.fillRect(x + w - 15, y + h - 14 - legAnim, 7, 14);
    } else {
      ctx.fillRect(x + 8, y + h - 14, 7, 14);
      ctx.fillRect(x + w - 15, y + h - 14, 7, 14);
    }

    ctx.strokeStyle = 'rgba(129, 212, 250, 0.4)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(x + w/2, y + h/2, w/2 + 4 + frostPulse, 0, Math.PI * 2);
    ctx.stroke();

    for (let i = 0; i < 3; i++) {
      const angle = (Date.now() / 500 + i * Math.PI * 2/3);
      const sparkX = x + w/2 + Math.cos(angle) * (w/2 + 8);
      const sparkY = y + h/2 + Math.sin(angle) * (h/2 + 8);
      ctx.fillStyle = 'rgba(179, 229, 252, 0.7)';
      ctx.beginPath();
      ctx.arc(sparkX, sparkY, 2, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  }
};
